    int N, K;
    cin >> N >> K;
    long long int a[N];
    for (int i = 0; i < N; i++)
    {
        cin >> a[i];
    }


    long long int ans = INF;
    if(K <= 1) ans = 0;
    for (int bit = 0; bit < (1 << (N-1)); bit++)
    {
        if(__builtin_popcount(bit) != K - 1) continue;
        long long int t = a[0];
        long long int sum = 0;
        for (int i = 1; i < N; i++)
