void MinAssign(ll &a, ll b) {
	a = min(a, b);
}

int BitCount(int bit) {
	bit = (bit & 0x55555555) + (bit >> 1 & 0x55555555);
	bit = (bit & 0x33333333) + (bit >> 2 & 0x33333333);
	bit = (bit & 0x0f0f0f0f) + (bit >> 4 & 0x0f0f0f0f);
	bit = (bit & 0x00ff00ff) + (bit >> 8 & 0x00ff00ff);
	return (bit & 0x0000ffff) + (bit >> 16 & 0x0000ffff);
}

int main() {
	cin >> n >> k;

	for (int i = 0; i < n; i++) {
		cin >> A[i];
	}

	fill(begin(dp), end(dp), INF);
	dp[0] = 0;

	for (int bit = 0; bit < (1 << n); bit++) {
		if (dp[bit] < INF) {
			int copy = bit;
			ll maxHeight = 0;

			for (int i = 0; i < n; i++, copy >>= 1) {
				if (copy != 0) {
					if (A[i] > maxHeight) {
						maxHeight = A[i];
					} else {
						maxHeight++;
					}
				} else {
					int add;
					if (A[i] > maxHeight) {
						add = 0;
					} else {
						add = maxHeight - A[i] + 1;
					}

					MinAssign(dp[bit | (1 << i)], dp[bit] + add);
				}
			}
		}
	}

	ll ans = INF;
	for (int bit = 0; bit < (1 << n); bit++) {
		if (BitCount(bit) == k) {
			ans = min(ans, dp[bit]);
		}
	}

