ll moddiv(ll n, ll a,ll m) {
	if (a == 0)return 1;
	if (a % 2 == 0) {
		ll b = moddiv(n, a / 2, m);
		return (b * b) % m;
	}
	else if (a % 2 == 1) return (n * moddiv(n, a - 1, m)) % m;
}

// グラフは<頂点,コスト>
void Dijkstra(ll v, vector<vector<pll>> graph,ll s, vl& ans) {
	auto comp = [](const pll a, const pll b) { return a.first > b.first; };
	priority_queue<pll, vector<pll>, decltype(comp)> que(comp);
	ans = vl(v, INF);
	ans[s] = 0;
	que.push(pll{ 0, s });
	pll a;
	while (!que.empty()) {
		ll c = que.top().first, p = que.top().second;
		que.pop();
		rep(i, graph[p].size()) {
			a = graph[p][i];
			if (ans[a.first] > a.second + c) {
				ans[a.first] = a.second + c;
				que.push(pll{ a.second + c,a.first });
			}
		}
	}
}

