void factorization(ll n, vector<pll> &ans) {
	for (ll i = 2; i * i <= n; i++) {
		if (n % i == 0)ans.push_back(make_pair(i, 0));
		while (n % i == 0) {
			ans.back().second++;
			n /= i;
		}
	}
	if (n != 1) ans.push_back(make_pair(n, 1));
}


