	for (int bit = 0; bit < (1 << n); bit++) {
		if (dp[bit] < INF) {
			int copy = bit;
			ll maxHeight = 0;

			for (int i = 0; i < n; i++, copy >>= 1) {
				if (copy != 0) {
					if (A[i] > maxHeight) {
						maxHeight = A[i];
					} else {
						maxHeight++;
					}
				} else {
					int add;
					if (A[i] > maxHeight) {
						add = 0;
					} else {
						add = maxHeight - A[i] + 1;
					}

					MinAssign(dp[bit | (1 << i)], dp[bit] + add);
				}
			}
		}
	}

	ll ans = INF;
	for (int bit = 0; bit < (1 << n); bit++) {
		if (BitCount(bit) == k) {
