				if(last >= a[i]){
					Ans += last + 1 - a[i];
					o += last + 1 - a[i];
				}
			}
			last = max(last, a[i] + o);
		}

		ans = min(ans, Ans);
		return;
	}
	if(id == n)
		return;
	gen(id + 1, t);
	mark[id] = true;
	gen(id + 1, t - 1);
	mark[id] = false;
}


