template<typename A,typename B>inline void chmin(A &a,B b){if(a>b)a=b;}
template<typename A,typename B>inline void chmax(A &a,B b){if(a<b)a=b;}
int main()
{
    int N,K;
    cin >> N >> K;
    vll A(N);
    cin >> A;
    ll ans = 1LL << 60;
    for(int bit=0; bit<(1<<N); bit++){
        vint idxs;
        ll cost = 0;
        for(int i=0; i<N; i++){
            if(bit&(1<<i)){
                idxs.pb(i);
            }
        }
        if((int)idxs.size() < K)continue;
        vint B;
        ll hmax = A[idxs[0]];
        ll diff = 1;
        for(auto a : A){
            B.pb(a);
        }
        for(int i=1; i<(int)idxs.size(); i++){
            int idx = idxs[i];
            if(hmax >= A[idx]){
                B[idx] += (hmax-B[idx]+diff);
                cost += hmax - A[idx] + diff;
                diff++;
            }else{
                hmax = A[idx];
                diff=0;
            }
        }

        int cnt = 1;
        hmax = B[0];
        REP(i,N){
            if((hmax < B[i])){
                hmax = B[i];
                cnt++;
            }
        }
        if(K <= cnt){
            ans = min(ans,cost);
        }
    }
    cout << ans << endl;
}

