ll solve(int n, int r, int k, vector<ll>a, ll acc, ll now, int used){
  if(n == r){
    if(used < k) return 1e9+7;
    return acc;
  }
  ll ret = 1e9+7;
  if(now+1 > a[r]){
    ret = solve(n, r+1, k, a, acc, now, used);
  }
  acc += max(ll(0), now+1 - a[r]);
  now = max(now+1, a[r]);
  return min(ret, solve(n, r+1, k, a, acc, now, used+1));
}

