using namespace std;
bool l[15];

long long calc(vector<int> a, int s) {

	int la = a[0];
	long long ans = 0;
	for (int i = 0; i < s; i++) {
		if (l[i]) {
			if (a[i+1] <= la) {
				int d = la - a[i+1] + 1;
				ans += d;
				a[i+1] += d;
				la = a[i + 1];
			}
		}
	}

	return ans;

}

long long func(vector<int>& a, int s, int n, int k) {

	if (n == s) {

		return calc(a,s);

	}
	else {

		long long na = -1, nb = -1;
		if (s - n > k) {
			l[n] = 0;
			na = func(a, s, n + 1, k);
		}
		l[n] = 1;
		nb = func(a, s, n + 1, k - 1);

		if (na == -1)
			return nb;
		else if (nb == -1)
			return na;
		else
			return min(na, nb);

	}

}

