          tmpA[i] = max_v + 1;
        }
        chmax(max_v, tmpA[i]);
        ++viewable;
      } else {
        if(tmpA[i] > max_v) {
          ++viewable;
          max_v = tmpA[i];
        }
      }
    }
    if(viewable >= k) chmin(rsl, tmp);
  }
  cout << rsl << endl;
}


