                    int dif = max(pre - a[i] + 1, 0LL);
                    tmp += dif;
                    pre++;
                }else {
                    pre = max(pre, a[i]);
                }
            }
        }

        if (ans == -1) ans = tmp;
        ans = min(ans, tmp);

    }

    cout << ans << endl;

    return 0;
}

