mint pow_kai(int a, int n) {//aのn乗を計算します。
    mint x = 1;
    while (n > 0) {//全てのbitが捨てられるまで。
        if (n & 1) {//1番右のbitが1のとき。
            x = x * a;
        }
        a = a * a;
        n >>= 1;//bit全体を右に1つシフトして一番右を捨てる。
    }
    return x;
}

