typedef long long ll;

const ll INFL = 1e18;

void solve(void){
    int N, K;
    cin >> N >> K;
    vector <ll> v(N);
    rep(N, i) cin >> v.at(i);
    int cnt = 1;
    while (cnt < N && v[cnt-1] < v[cnt]) cnt++;
    K -= cnt;
    N -= cnt;
    if (K <= 0) {
        cout << 0 << endl;
        return;
    }
    ll ans = INFL;
    rep((1<<N), n) {
        if (bitcnt(n) != K) continue;
        ll h = v[cnt-1], cost = 0LL;
        rep(N, i) {
            if (n >> i & 1) {
                if (h < v[i+cnt]) h = v[i+cnt];
                else {
                    cost += h + 1 - v[i+cnt];
                    h++;
                }
            }
        }
        ans = min(ans, cost);
    }
    cout << ans << endl;
}

