int calc_cost(int bit){
  ll ret = 0;
  vector<int> index;
  for(int i = 0; i<N;i++){
    if(bit&(1<<i)) index.push_back(i);
  }
  if (index.size() == K){
    ll height = 0;
    for(int i=0;i < index[0];i++){
      if (height < A[i]) height = A[i];
    }
    for(auto a:index){
      if(A[a] > height){
        height = A[a];
      }
      else{
        height++;
        ret += height - A[a];
      }
    }
  }
  if(ret==0) return -1;
  if(ret!=0) return ret;
}

