struct fenwick {
    vector<ll> bit;
    ll n;
    fenwick(ll n, vector<ll> v) {
        this->n = n;
        bit.assign(n, 0);
        for (ll it = 0; it < n; it++) {
            add(it, v[it]);
        }
    }

    ll sum(ll idx) {
        if (idx < 0)
            return 0;
        ll ret = 0;
        for (; idx >= 0; idx = (idx & (idx + 1)) - 1) {
            ret += bit[idx];
        }
        return ret;
    }
    void add(ll idx, ll x) {
        for (; idx < n; idx = idx | (idx + 1)) {
            bit[idx] += x;
            bit[idx] = max(0LL, bit[idx]);
        }
    }
};
