    string ret = "1";
    rep(i, n - 1)
    {
        if (x % 2)
        {
            ret += '1';
            c++;
        }
        else
        {
            ret += '0';
        }
        x /= 2;
    }
    if (c == k - 1)
        r = true;

    return make_pair(ret, r);
}

ll cost(int a[], int n, string s)
{
    ll res = 0;
    int height = 0;
    rep(i, n)
    {
        if (s[i] == '1')
        {
            if (height < a[i])
                height = a[i];
            else
            {
                res += height + 1 - a[i];
                height++;
            }
        }
        else
        {
            if (height < a[i])
            {
                height = a[i];
                res += a[i] - height;
            }
        }
    }
    return res;
}

