int main()
{
  int N, K;
  cin >> N >> K;
  vector<long long> A(N);
  for (int i = 0; i < N; i++) cin >> A.at(i);

  long long ans = INF;

  vector<int> B(N);
  B.at(0) = 1;

  for (int i = 0; i < pow(2, N - 1); i++)
  {
    int k = 1;
    for (int j = 1, p = 1; j < N; j++)
    {
      B.at(j) = i / p % 2;
      if (B.at(j) == 1) k++;
      p *= 2;
    }

