void getInput() {
    cin>>N>>K;
    A = vector<int>(N, 0);
    for(int i=0; i<N; ++i) {
        cin>>A[i];
    }
}

void solve() {
    int score = 10e8;
    for(int i=0; i< 1<<N; ++i) {
        // cout<<i<<"bitset: "<<bitset<16>(i)<<endl;
        int height = A[0];
        int cnt = 0;
        int cost = 0;
        for(int j=0; j<N; ++j) {
            if (j==0) { cnt++; continue;}
            if (height < A[j]) {
                cnt++;
                height = A[j];
                continue;
            } else {
                bool canUp = (i & 1<<j);
                if (canUp) {
                    cost += height + 1 - A[j];
                    height++;
                    cnt++;
                }
            }
        }
        if (cnt >= K) {
            score = min(score, cost);
        }
        // print("cost", cost, "cnt", cnt);

    }
    cout<<score<<endl;
}

