using namespace std;
using ll = long long;

int for_each_combination(int n, int k, const vector<int> &p, const vector<bool> &b, function<int(vector<int>, vector<bool>)> f, int i = 0) {
    if(k <= 0 || k > n - i) return INT_MAX / 2;
    if(k == 1) {
        int res = INT_MAX;
        int cos = f(p, b);
        for(int j = i; j < n; j++) {
            vector<bool> ptn = b;
            ptn[j] = true;
            res = min(res, f(p, ptn) - cos);
        }
        return res;
    }
    if(k == n - i) {
        vector<bool> bb = b;
        for(int j = i; j < n; j++) bb[j] = true;
        return f(p, bb);
    }
    // k >= 2
    // use it

    int cos = f(p, b);
    vector<bool> bb = b;
    bb[i] = true;
    int bbcos = f(p, bb);
    int u_cos = for_each_combination(n, k - 1, p, bb, f, i + 1);
    int uu_cos = for_each_combination(n, k, p, b, f, i + 1);
    return min(bbcos + u_cos, cos + uu_cos);
}

int main() {
    int N, K;
    cin >> N >> K;
    vector<int> A(N);
    for(auto &x: A) cin >> x;
    auto calc = [](vector<int> p, vector<bool> b) {
        int h = p[0];
        int res = 0;
        for(int i = 1; i < p.size(); i++) {
            if(b[i] == true) {
                if(p[i] <= h) {
                    res += h - p[i] + 1;
                    h++;
                }
            }
            h = max(h, p[i]);
        }
        return res;
    };
    cout << for_each_combination(N, K, A, vector<bool>(N, false), calc) << endl;
}

