                before = A[cp[i]];
            } else {
                sum += before + 1 - A[cp[i]];
                before++;
            }
        }
        ans = min(ans, sum);
    } while (next_combination(ALL(L), K - 1)); // 次の順列を生成

    cout << ans << endl;

    return 0;
}

