                    int diff = cur - A[i];
                    tmp += diff + 1;
                    cur += 1;
                } else {
                    cur = A[i];
                }
            } else { // 見えない状態にする
                if (A[i] > cur && i > 0) {
                    int diff = A[i] - cur;
                    tmp += diff;
                    cur = A[i];
                }
            }
        }

        if (ans == -1 || tmp < ans) {
            ans = tmp;
            dump(b, ans);
        }
    }
    cout << ans << endl;
}

