      ll nx = A.at(idx.front());
      if(st >= nx){
        cnt += st-nx+1;
        st = st+1;
      }else{
        st = nx;
      }
      k++;
      idx.pop();
    }
    ans = min(ans,cnt);
  }
  cout << ans << endl;
}

