/*FUNCs=================================================*/
//{0,1,...,n-1}のn個の要素数のbit集合から要素数k個の部分集合のみ列挙して探索する
//k = 0ではうまく動かないので例外処理が必要
int next_combination(int bit){
    int x = bit & -bit, y = bit + x;
    return(((bit & ~y) / x) >> 1) | y;
}

/*MAIN==================================================*/
signed main(){
    double START_TIME = clock();
    cin.tie(nullptr);
    ios::sync_with_stdio(false);
//    cout << fixed << setprecision(15);

    i32 n,k; cin >> n >> k;
    --n, --k;
    i32 front_h; cin >> front_h;
    vi a(n); rep(i,n) cin >> a[i];

    i32 ans = inf;
    for(i32 bit = (1<<k)-1; bit < (1<<n); bit = next_combination(bit)) {
        i32 tmp = 0;
        i32 before_h = front_h;
        for(i32 i = 0; i < n; ++i) {
            if(bit >> i & 1) {
                if(a[i] <= before_h) {
                    ++before_h;
                    tmp += before_h - a[i];
                }
            }
            chmax(before_h, a[i]);
        }
        chmin(ans, tmp);
    }
    if(ans == inf) ans = 0;
    cout << ans << '\n';

//     printf("ElapsedTime: %5.3f ms\n",1000*((clock()-START_TIME)/CLOCKS_PER_SEC));
}

