    vvi v = comb().c(n-1, n-k);
    ll ans = -1;
    for (vi vec : v) {
        vi iv(n-1);
        iota(ALL(iv), 1);
        for (int n : vec) {
            auto res = remove(ALL(iv), n+1);
            iv.erase(res, iv.end());
        }
        int h = a[0];
        ll tmp = 0;
        for (int n : iv) {
            if (h < a[n]) {
                h = a[n];
            } else {
                h++;
                int dif = h - a[n];
                tmp += dif;
            }
        }

        if (ans == -1) ans = tmp;
        ans = min(ans, tmp);

    }

    cout << ans << endl;

    return 0;
}

