  vector<int> a(N);
  rep(i,N) cin >> a.at(i);//入力終了

  ll ans=1000000000000000000;//コスト

  bitrep(N-1){//bit全探索(2番目以降)

    vector<bool> b(N,false);//2番目以降の建物を見せるかどうか
    rep(i,N-1){//どの建物を見えるようにするか
      if(bit&(1<<i))
      b.at(i+1)=true;
    }

    int view=1;//見える建物の数(先頭は確定)
    int H1max=0;//見せない建物のうち最も高いもの
    for(int i=1;i<N;i++){
      if(b.at(i)) view++;
      else H1max=max(H1max,a.at(i));
    }
    if(view<K) continue;//先頭を合わせてK個未満の建物しか見えない場合はスルー

    ll temp=0;//かかるコスト
    vector<int> c(N);//元の配列aが書き変わらないように別のものを用意

    if(H1max>a.at(0)){//見せない建物を隠す
      temp+=H1max-a.at(0);
      c.at(0)=H1max;
    }
    else c.at(0)=a.at(0);

    int H2max=c.at(0);//その建物よりも前で最も高い建物の高さ

    for(int i=1;i<N;i++){
      c.at(i)=a.at(i);//aを仮配列cに移し替える
      if(b.at(i)){
