ll cost(vector<int> &c) {
  ll s = 0;
  int p=0;
  for(int i=0; i<c.size(); i++) {
    s += max(0, (r[c[i]]+1+p) - a[c[i]]);
    if((r[c[i]]+1+p) - a[c[i]] > 0) p++;
    else p = 0;
  }
  return s;
}

ll dfs(vector<int> &c, int index=1) {
  if(c.size() == k-1) return cost(c);
  int rest = n-index;
  ll s = INF;
  if(c.size()+rest < k-1) return s;
  c.push_back(index);
  s = min(s, dfs(c, index+1));
  c.pop_back();
  s = min(s, dfs(c, index+1));
  return s;
}

