      }
    }

    if(S.size()>=K){
      ll cnt=0;

      if(t>0){
        ll mx=0LL;
        for(int i=0; i<t; ++i){
          chmax(mx,A[i]);
        }
        if(mx>S.at(0)){
          cnt+=mx-S.at(0)+1;
          S.at(0)=mx+1;
        }
      }

      for(int i=1; i<S.size(); ++i){
        if(S.at(i)<=S.at(i-1)){
          cnt+=S.at(i-1)-S.at(i)+1;
          S.at(i)=S.at(i-1)+1;
        }
      }
      chmin(ans,cnt);
    }
  }

  cout<<ans<<endl;
  return 0;
}

