int_fast8_t popcount(uint32_t bits) {
#ifdef __GNUC__
	return __builtin_popcount(bits);
#endif
	bits = bits - (bits >> 1 & 0x55555555);
	bits = (bits & 0x33333333) + (bits >> 2 & 0x33333333);
	bits = bits + (bits >> 4) & 0x0f0f0f0f;
	bits = bits * 0x01010101;
