    ll n, k; cin >> n >> k;
    vector<ll> a(n);
    for (ll i = 0; i < n; ++i) cin >> a[i];

    vector<ll> v;
    auto ans = solve(n, k, 0, v, a);
    cout << ans << endl;
    return 0;
}

