const ll LINF = 2e18;
const int INF = 1e9;

ll N, K;
vector<ll> a;

void solve() {
  ll cost = 0;
  ll vis;
  vector<ll> s(N), t(N);

  t.at(0) = a.at(0);
  s.at(0) = 0;
  vis = 1;

  FOR(i, 1, N) {
    if (a.at(i) > t.at(i - 1)) {
      t.at(i) = a.at(i);
      vis++;
    } else {
      t.at(i) = t.at(i - 1);
    }
    s.at(i) = t.at(i) - a.at(i);
  }

  while (vis < K) {
    ll smin = LINF;
    ll sminidx = -1;
    rep(i, N) {
      if (s.at(i) > 0 && s.at(i) < smin) {
        smin = s.at(i);
        sminidx = i;
      }
    }
    cost += smin + 1;
    a.at(sminidx) += smin + 1;
    vis++;

    FOR(i, sminidx, N) {
      if (t.at(i) == a.at(i)) {
        a.at(i)++;
        cost++;
      }
      t.at(i)++;
      s.at(i) = t.at(i) - a.at(i);
    }
  }

  cout << cost << endl;
}

