void solve() {
    ll n, k;
    cin >> n >> k;
    vll a(n);
    cin >> a;

    ll mic = INF;
    REP(state, 0, 1 << (n - 1)) {
        // 一番左は嵩上げしない
        ll mi = a[0];
        ll cost = 0;
        ll cnt = 1; // 何色見えたか
        REP(j, 0, n - 1) {
            if (a[j + 1] > mi) // 嵩上げ不要
                mi = a[j + 1], cnt++;
            else if ((state >> j) & 1) { // 嵩上げ実行
                mi++, cnt++;
                cost += mi - a[j + 1];
            }
        }
        // dump(state, cnt, cost);
        if (cnt >= k) chmin(mic, cost);
    }
    cout << mic << endl;
}

