int c(const vector<int> &p, const vector<bool> &b) {
    int h = p[0];
    int res = 0;
    for (int i = 1; i < p.size(); i++)
    {
        if (b[i] == true)
        {
            if (p[i] <= h)
            {
                res += h - p[i] + 1;
                h++;
            }
        }
        h = max(h, p[i]);
    }
    return res;
}

int calc(int n, int k, const vector<int> &p) {
    vector<bool> b(n);
    for(int i = 0; i < k; i++) b[n - 1 - i] = true;
    int m = INT_MAX;
    do {
        m = min(m, c(p, b));
    } while(next_permutation(b.begin(), b.end()));
    return m;
}

