signed main() {

    SS(int, N, K);
    SV(int, A, N);

    dp[0][0][0] = 0;

    auto update = [&](int a, int b, int c, int x) -> void {
        // debug(a, b, c, x);
        if (dp[a][b].count(c) == 0) dp[a][b][c] = x;
        else chmin(dp[a][b][c], x);
    };

    vector<int> mx(N + 1, 0);
    REP(i, 1, N + 1) chmax(mx[i], max(mx[i - 1], A[i - 1]));

    REP(i, N) {
        REP(j, N) {
            EACH(p, dp[i][j]) {
                int hei, val;
                tie(hei, val) = p;
                {   // i番目を採用
                    int need = max<ll>(0, (max<ll>(mx[i], hei) + 1) - A[i]);
                    update(i + 1, j + 1, A[i] + need, val + need);
                }
                {   // i番目を採用しない
                    update(i + 1, j, hei, val);
                }
            }
        }
    }

    int res = INF;

    REP(i, K, N + 1) {
        EACH(e, dp[N][i]) {
            chmin(res, e.second);
        }
    }

