tuple<LD,LD,LD> point2line(LD y1,LD x1,LD y2,LD x2){
  LD A = y1-y2;
  LD B = x2-x1;
  LD C = -A*x1-B*y1;
  return make_tuple(A,B,C);
}
LD dist_point_line(LD y1,LD x1,LD A,LD B,LD C){
  return abs(A*x1+B*y1+C)/sqrtl(A*A+B*B);
}

string rec(LL n,LL k, VLL &C){
  if(k==0){
    if(n==0){
      return "A";
    }
    if(n==1){
      return "B";
    }    
    return "C";
  }

  if(n==0){
    return "A";
  }
  n -=1;
  if(n>=0 and n<C[k-1]){
    return rec(n,k-1,C);
  }
  n -= C[k-1];
  if(n==0){
    return "B";
  }
  n -=1;
  if(n>=0 and n<C[k-1]){
    return rec(n,k-1,C);
  }
  n -= C[k-1];
  if(n==0){
    return "C";
  }
  dump("error");
  return "-";
}


