template <typename T>
struct Kruskal
{

    struct edge
    {
        ll from, to;
        T cost;
        ll used;
        edge() {}
        edge(ll from, ll to, T cost) : from(from), to(to), cost(cost), used(0) {}
        bool operator<(const edge &e) const
        {
            return cost < e.cost;
        }
    };

    ll n;
    vector<ll> p, r;
    vector<edge> edges;

    Kruskal() {}
    Kruskal(ll n) : n(n) {}

    void init(ll n)
    {
        r.assign(n, 1);
        p.resize(n);
        iota(p.begin(), p.end(), 0);
    }

    ll find(ll x)
    {
        return (x == p[x] ? x : p[x] = find(p[x]));
    }

    bool same(ll x, ll y)
    {
        return find(x) == find(y);
    }

    void unite(ll x, ll y)
    {
        x = find(x);
        y = find(y);
        if (x == y)
            return;
        if (r[x] < r[y])
            swap(x, y);
        r[x] += r[y];
        p[y] = x;
    }

    void add_edge(ll u, ll v, T c)
    {
        edges.emplace_back(u, v, c);
    }

    T build()
    {
        sort(edges.begin(), edges.end());
        init(n);
        T res = 0;
        for (auto &e : edges)
        {
            if (!same(e.from, e.to))
            {
                res += e.cost;
                unite(e.from, e.to);
                e.used = 1;
            }
        }
        return res;
    }
};

int LIS(int a[], int n)
{
    vector<int> A(n, 0x3f3f3f3f);
    for (int i = 0; i < n; i++)
        *lower_bound(A.begin(), A.end(), a[i]) = a[i];
    return find(A.begin(), A.end(), 0x3f3f3f3f) - A.begin();
}

string maze[1010];
ll bfs(ll H, ll W, ll sx, ll sy, ll gx, ll gy)
{

    int dx[4] = {1, 0, -1, 0};
    int dy[4] = {0, 1, 0, -1};

    vector<vector<ll>> dist(H, vector<ll>(W, -1));
    dist[sy][sx] = 0;

    queue<PL> q;
    q.push({sy, sx});
    while (!q.empty())
    {
        ll x, y;
        tie(y, x) = q.front();
        q.pop();
        if (y == gy && x == gx)
        {
            break;
        }
        for (int t = 0; t < 4; t++)
        {
            ll nx = x + dx[t], ny = y + dy[t];
            if (nx < 0 || ny < 0 || nx >= W || ny >= H || dist[ny][nx] != -1 || maze[ny][nx] == '#')
            {
                continue;
            }

            dist[ny][nx] = dist[y][x] + 1;
            q.push({ny, nx});
        }
    }

    return dist[gy][gx];
}

vector<vector<ll>> warshall_floyd(ll n , vector<vector<ll>> g, ll INF)
{
    //init vector<vector<ll>> c(10,vector<ll>(10,0));

    for (int k = 0; k < n; k++)
    {
        for (int i = 0; i < n; i++)
        {
            for (int j = 0; j < n; j++)
            {
                if (g[i][k] == INF || g[k][j] == INF)
                    continue;
                g[i][j] = min(g[i][j], g[i][k] + g[k][j]);
            }
        }
    }

    return g;
}

struct Dijkstra
{

   ll n;
   vector<vector<pair<ll, ll>>> Edges;
   vector<ll> Dist;
   vector<ll> Prev;
   vector<ll> PathNum;

   Dijkstra(ll n) : n(n), Edges(n), Dist(n), Prev(n), PathNum(n)
   {
      Prev.assign(n, -1);
   };

   void add_edge(ll a, ll b, ll c, bool directed = true)
   {
      if (directed)
      {
         Edges[a].emplace_back(make_pair(b, c));
      }
      else
      {
         Edges[a].emplace_back(make_pair(b, c));
         Edges[b].emplace_back(make_pair(a, c));
      }
   }
   // O((E+V)logV)
   void build(int start)
   {
      priority_queue<P, vector<P>, greater<P>> queue;
      fill(Dist.begin(), Dist.end(), 1e+18);//1e18 !?!?
      Dist[start] = 0;
      PathNum[start] = 1;
      queue.push(PL(0, start));

      while (!queue.empty())
      {
         PL p = queue.top();
         queue.pop();
         int v = p.second;
         if (Dist[v] < p.first)
            continue;

         for (int i = 0; i < Edges[v].size(); i++)
         {
            PL e = Edges[v][i];
            if (Dist[e.first] > Dist[v] + e.second)
            {
               Dist[e.first] = Dist[v] + e.second;
               queue.push(P(Dist[e.first], e.first));

               Prev[e.first] = v;

               PathNum[e.first] = PathNum[v];
            }
            else if (Dist[e.first] == Dist[v] + e.second)
            {
               PathNum[e.first] += PathNum[v];
               PathNum[e.first] %= MOD;
            }
         }
      }
   }

   ll dist(ll t)
   {
      return Dist[t];
   }

   vector<ll> get_path(ll t)
   {
      vector<ll> path;
      for (; t != -1; t = Prev[t])
      {
         path.push_back(t);
      }
      reverse(path.begin(), path.end());
      return path;
   }

   ll get_path_num(ll t)
   {
      return PathNum[t];
   }

