ll dfs(int i, int k, ll sum, ll ma){
    if (k == K) return sum;
    if (i == N) return longinf;

    ll ret;
    if (ma < a[i]) {
        ret = dfs(i + 1, k + 1, sum, a[i]);
    } else {
        ret = min(dfs(i + 1, k + 1, sum + ma + 1 - a[i], ma + 1), dfs(i + 1, k, sum, ma));
    }

    return ret;
}

