	vector<int> s(n, 0);
	vector<vector<int>> ss(pow(2, n), vector<int>(n, 0)); //組み合わせは2^n個ある
	int counter = 0;;

	makecombi(0, n, s, ss, counter);

//	cout << endl << endl;
	long long mincost = 100000000000;
	for (int i = 0; i < counter; i++) {
		int tmp = 0;
		for (int j = 0; j < n; j++) {
