std::vector<long long> a;
long long repeatedpow(long long x, long long y){
    if(y == 0) return 1;
    if(y % 2 == 1) return repeatedpow(x, y -1)*x;
    else return repeatedpow(x, y / 2)* repeatedpow(x, y / 2);
}
int main(){
    std::cin >> N >> K;
    a.resize(N);
    for(int i = 0; i < N; i++) std::cin >> a[i];
    long long ans = INF;
    long long k = repeatedpow(2, K - 1) - 1;
    long long k1 = repeatedpow(2, K) - 1;
    for(int bit = k; bit < (1 << N - 1); bit += 2){
        std::vector<int> sele(N - 1, 0);
        for(int i = 0; i < N - 1; i++){
            if(bit & (1 << i)) sele[i] = 1;
        }
        long long res = 0;
        long long M = a[0];
        for(int i = 0; i < N - 1; i++){
            if(sele[i] == 1 && M >= a[i + 1]){
                res += M + 1 - a[i + 1];
                M++;
            }
            M = std::max(M, a[i + 1]);
        }
        ans = std::min(ans, res);
    } 
    std::cout << ans << std::endl;
}

