void Calc(int index, int kCount, ll prevHeight, ll value) {

    if(kCount == k) {
        minValue = min(value, minValue);
        return;

    }

    ll maxHeight = prevHeight;

    for(int i = index; i >= 0; --i)
        maxHeight = max(maxHeight, b[i]);

    for(int i = index + 1; i < n; ++i) {

