		if(num>=k) mi=min(mi,sum);
		return;
	}
	dfs(idx+1,ma,sum,num);
	if(ma<a[idx]) dfs(idx+1,a[idx],sum,num+1);
	else {
		ll cost=ma-a[idx]+1;
		dfs(idx+1,ma+1,sum+cost,num+1);
	}
}

