/*FUNCs=================================================*/
//{0,1,...,n-1}のn個の要素数のbit集合から要素数k個の部分集合探索。
int next_combination(int sub){
    int x = sub & -sub, y = sub + x;
    return(((sub & ~y) / x) >> 1) | y;
}


