int solve(int n, int r, int k, vector<int>a, int acc, int now, int used){
  if(n == r){
    if(used < k) return 1e9+7;
    return acc;
  }
  int ret = 1e9+7;
  if(now+1 > a[r]){
    ret = solve(n, r+1, k, a, acc, now, used);
  }
  acc += max(0, now+1 - a[r]);
  now = max(now+1, a[r]);
  return min(ret, solve(n, r+1, k, a, acc, now, used+1));
}

