    ll heighst = b[0];
    for (int i = 1; i < N; i++) {
        if (bit & (1 << i)) {
            ll cost_i = max((ll)0, heighst - b[i] + 1);

            heighst = max(b[i], heighst + 1);

            cost += cost_i;
        }
        else heighst = max(b[i], heighst);
    }

    return cost;
}

