    for (int bit = 0; bit < (1 << N); bit++)
    {
        ll prev = -1;
        ll cost = 0;
        vector<ll> copy(N);
        copy = a;
        for (int i = 0; i < N; i++)
        {
            if (bit & (1 << i))
            {
                // i番目の建物を増築する
                if (copy[i] <= prev)
                {
                    cost += prev + 1 - copy[i];
                    copy[i] = prev + 1;
                    prev = copy[i];
                }
                else
                {
                    prev = copy[i];
                }
            }
            else
            {
                prev = max(prev, copy[i]);
            }
        }

        prev = -1;
        ll cnt = 0;
        for (int i = 0; i < N; i++)
        {
            if (prev < copy[i])
            {
                cnt++;
                prev = copy[i];
            }
        }
        if (K <= cnt)
        {
            ans = min(ans, cost);
        }
    }

    cout << ans << endl;

    return 0;
}

