inline void solve(void){
  long N,K;
  in(N,K);
  vector<cpp_int>a(N);
  rep(i,N)in(a[i]);
  cpp_int ans=10000000000000000;
  for(int i=0;i<1<<N;i++){
    if(__builtin_popcount(i)<(int)K)continue;
    cpp_int now,cost=0;
    bool is_first=true;
    rep(j,N){
      if(i>>j&1){
        if(is_first){
          if(a[0]>=a[j]&&j!=0){
            now=a[0]+1;
            cost+=a[0]-a[j]+1;
          }else{
            now=a[j];
          }
          is_first=false;
        }else{
          if(a[j]<=now){
            cost+=now-a[j]+1;
            now++;
          }else now=a[j];
        }
      }
    }
    chmin(ans,cost);
  }
  out(ans);
}
int main(int argc,char**argv){
  BEGIN;
  solve();
  END;
}

