#include <bits/stdc++.h>

using namespace std;

typedef pair<int, int> P;
typedef long long ll;

int N, K;
vector<ll> A;

void solve(){
    ll m = 1e16;
    ll height = A[0];

    for (int b = 0; b < (1 << N); b++)
    {
        height = A[0];
        ll cost = 0;
        bitset<20> bs(b);
        int cnt = 0;
        vector<int> v;

        for (int i = 0; i < N; i++){
            if(bs.test(i)){
                cnt++;
                v.push_back(i);
            }
        }

        if(cnt == K && bs.test(0)){
            for (int i = 1; i < (int)v.size(); i++){
                ll dif = height - A[v[i]];
                if(dif >= 0){
                    cost += dif + (ll)1;
                    height += (ll)1;
                    continue;
                }

                height = A[v[i]];
            }

                m = min(m, cost);
        }
    }


    cout << m << endl;
}


int main(){
    cin >> N >> K;
    for (int i = 0; i < N; i++)
    {
        ll a;
        cin >> a;
        A.push_back(a);
    }

    solve();

    return 0;

}

