int main() {

    int N, K; cin >> N >> K;
    int a[N]; rep(i,N) cin >> a[i];
    ll ans = INF;
    for (int bit = 0; bit < (1<<(N-1)); ++bit) {
        int visible = 0;
        ll tmp = 0;
        int tallest = a[0];
        int b[N-1];
        rep(i,N-1) b[i] = a[i+1];
        rep(i,N-1) {
            if (bit & (1<<i)) {
                ++visible;
                if (i == 0) {
                    tmp += max(0, tallest + 1 - b[i]);
                    tallest = max(b[i], a[0] + 1);
                }
                else {
                    tmp += max(0, tallest + 1 - b[i]);
                    tallest = max(b[i], tallest + 1);
                }
            }
        }
        if (visible == K - 1) ans = min(ans,tmp);
    }
    out(ans);

    return 0;
}

