LL f(vector<LL>& v){
	LL max = v[0];
	LL ans = 1;
	int size = v.size();
	for(int i=1;i<size;++i){
		if( max < v[i] ){
			++ans;
			max = v[i];
		}
	}
	return ans;
}

//posを見えるようにするためのコスト
pair<LL,LL> cost(vector<LL>& v,int pos){
	LL ans = 0;
	LL add = 0;
	LL MAX = 0;
	int size = v.size();
	vector<bool> hi(size,false);
	hi[0] = true;
	MAX = v[0];
	for(int i=1;i<size;++i){
		if( MAX < v[i] ){
			hi[i] = true;
			MAX = v[i];
		}
	}

	//posより前の最大値
	MAX = 0;
	for(int i=0;i<pos;++i){
		MAX = max(MAX,v[i]);
	}
	if( MAX >= v[pos] ){
		add = MAX -v[pos] + 1;
		ans = MAX -v[pos] + 1;
		MAX = MAX+1;
	}else{
		//none
		MAX = v[pos];
	}


	for(int i=pos+1;i<size;++i){
		if( hi[i] ){
			if( MAX < v[i] ){
				break;
			}else{
				ans += MAX-v[i]+1;
			}
		}
	}
	pair<LL,LL> res(ans,add);
	return res;
}
