	for(int i=0;i<N;++i){
		cin >> A[i];
		if( i ){
			diff[i] = A[i]-A[i-1];
		}
	}

	LL ans = 0;
	pair<LL,LL> MIN,temp;
	while( f(A) < K ){
		MIN.first = LINF;
		int pos = -1;
		for(int i=N-1;i>0;--i){
			temp = cost(A,i);
			if( temp.first > 0 && temp.first < MIN.first){
				MIN = temp;
				pos = i;
			}
		}
		A[pos] += MIN.second;
		ans += MIN.second;
	}
	cout << ans << endl;
}

