	ints a = input(N);

	int minCost = INT64_MAX;
	int size = pow(2, N);
	REP(i, size) {
		int h = 0;
		int cost = 0;
		int cnt = 0;
		REP(j, N) {
			if ((i >> j) & 1) {
				++cnt;
				if (cnt > K) {
					break;
				}
				if (h < a[j]) {
					h = a[j];
				}
				else {
					cost += (h - a[j]) + 1;
					h += 1;
				}
			}
			else {
				chmax(h, a[j]);
			}
		}
		if (cnt != K) {
			continue;
		}
		chmin(minCost, cost);
	}

	output(minCost);
}

