    if(t==N){
        ll temp = 0;
        ll num = 0;
        ll last = 0;
        for(int i=0;i<N;i++){
            if(use[i]){
                num++;
                temp += max(0ll,last+1-a[i]);
                last = max(last+1,a[i]);
