using namespace std;
typedef long long int ll;

int main()
{
    ll n,k;
    cin >> n >> k;
    vector<pair<ll,ll>>V,v;
    vector<bool>F,f;
    V.resize(n);
    F.resize(n);
    ll tmp = 0;
    for(ll i = 0; i < n; i++)
    {
        cin >> V[i].first;
        if(tmp < V[i].first)
        {
            tmp = V[i].first;
            V[i].second = tmp;
            F[i] = true;
        }
        else
        {
            F[i] = false;
            V[i].second = tmp;
        }
    }
    //V[i] = {(建物iの高さ),(自分自身と自分よりも前の建物のうち高さの最大)}
    //F[i] = 建物iが見えればtrue、見えなければfalse
    //V[i].first >= V[i].second　かつ　V[i] = true　の時、建物iは見える

    ll result = 0;
    for(ll bit = 0; bit <(1<<n); bit++) //O(2^n)
    {
        v = V;
        f = F;
        ll sum = 0;
        ll count = 0;
        for(ll i = 0; i < n; i++) //O(n)
        {
            if((bit&(1<<i))&&(f[i] == false))
            {
                sum += v[i].second + 1 - v[i].first;
                v[i].first = v[i].second + 1;
                v[i].second = v[i].first;
                f[i] = true;
                for(ll j = i + 1; j < n; j++) //0(n) (ここまでO(n^7))
                {
                    if(v[j].first <= v[i].first)
                    {
                        f[j] = false;
                        v[j].second = v[i].first;
                    }
                }
            }
        }
        for(auto x:f)
        {
            if(x)
            {
                count++;
            }
        }
        if(count >= k)
        {
            if(result == 0)
            {
                result = sum;
            }
            else
            {
                result = min(result,sum);
            }
        }
    }
    cout << result << endl;
    return 0;
}

