using int64 = long long;

int64 calc(const vector<int64>& a, const vector<int64>& s) {
    int64 res = 0;
    int64 pre = 0;
    int n = a.size();
    auto si = s.begin();
    for (int i=0; i<n; i++) {
        int ad = 0;
        if (i == *si) {
            ad = max(0LL, pre - a[i] + 1);
            res += ad;
            si++;
            if (si == s.end()) break;
        }
        pre = max(pre, a[i] + ad);
    }
    return res;
}

int64 dfs(const int& i, const int& k, const vector<int64>&a, vector<int64> s) {
    if (s.size() == k) return calc(a,s);
    if (i >= a.size()) return INT_MAX;
    int64 res = INT_MAX;

    res = min(res, dfs(i+1, k, a, s));
    s.push_back(i);
    res = min(res, dfs(i+1, k, a, s));
    return res;
}


