        cin >> heights[i];
    }

    long long min_cost = 1000000000000;
    for(int i = 0; i < (1 << n); i++) {
        auto poses = iter_flag(i);
        if(poses.size() != k) continue;
        if(poses[0] != 0) continue;
        long long cost = 0;
        int cur_height = heights[poses[0]];
        for(int b = 1; b < k; b++) {
            if(cur_height >= heights[poses[b]]) {
                cost += cur_height + 1 - heights[poses[b]];
