int main(void)
{
	ll N, K; cin >> N >> K;
	vt<ll> a(N); each(i, e, a) cin >> e;

	NT_NyaaBit bit;
	ll ans = llong_max;
	rep(i, 0, Pow2(N))
	{
		if (bit.Count(i) != K || bit.Test(i, 0) != 1) continue;
		ll sum = 0;
		ll test = a[0];
		rep(j, 1, bit.Size(i))
		{
			test = max(test, a[j-1]);
			if (bit.Test(i, j) == 0) continue;
			if (a[j] <= test)
			{
				sum += test - a[j] + 1;
				a[j] = test + 1;
			}
		}
		ans = min(ans, sum);
	}

	cout << ans << endl;
	return 0;
}

