int main() {
   int N,K;
   cin >> N >> K;
   int A[N];
   for (int i=0; i<N; i++) {
       cin >> A[i];
   }
   int total=2000000000;
   for (int tmp=0; tmp<(1<<15); tmp++) {
       bitset<15> s(tmp);
       int B[K],C[N],count=0;
       if (!s.test(count)) continue;
       for (int i=0; i<N; i++) {
           if (s.test(i)) count++;
       }
       if (count!=K) continue;
       count=0;
       for (int i=0; i<N; i++) {
           if (s.test(i) && count!=K) {
               B[count]=i;count++;
           }
           else C[i]=A[i];
       }
       C[0]=A[0];
       int n=A[0];
       count=0;
       for (int i=1; i<K; i++) {
           int a=B[i-1];
           int b=B[i];
           if (n<C[a]) n=C[a];
           for (int j=a; j<b; j++) {
               if (j==b-1 && n<A[b]) C[b]=A[b];
               else if (j==b-1) {
                   C[b]=n+1;
                   count+=n+1-A[b];
               }
           }
       }
       if (total>count) total=count;
   }
   cout << total << endl;
