int N,K,a[20],base[20],maxheight,ans,dp;

int main(){
    ios_base::sync_with_stdio(0); cin.tie(0);

    cin >> N >> K;
    for(int i=1;i<=N;i++){
        cin >> a[i];
        base[i] = max(base[i-1],a[i]);
    }
    dp = 1e9+27;
    for(int i=1;i<(1<<N);i++){
        int num = i;
        int bits = __builtin_popcount(num);
        if(bits==K){
            int head = 31-__builtin_clz(num);
            ans = 0;
            for(int j=head;j>=0;j--){
                if(j==head) maxheight = base[N-j];
                else if(num&(1<<j)){
                    maxheight++;
                    if(a[N-j]<maxheight) ans += maxheight - a[N-j];
                    else maxheight = a[N-j];
                }
            }
            dp = min(ans,dp);
        }
    }

    cout << dp << endl;

    return 0;
}

