      int MAX = 0;
      for (int j = 0; j < i; ++j) MAX = max(b[j], MAX);
      if (MAX >= b[i]) {
        cost += MAX - b[i] + 1;
        b[i] = MAX + 1;
      }
    }

    int cnt = 0;
    int MAX;
    for (int i = 0; i < N; ++i) {
      if (i == 0) {
        ++cnt;
        MAX = b[i];
      } else {
        if (MAX < b[i]) ++cnt;
        MAX = max(b[i], MAX);
      }
    }

    if (cnt >= K) ans = min(cost, ans);
  }

  cout << ans << endl;
  return 0;
}

