int main()
{
  ios::sync_with_stdio(false);
  cin.tie(nullptr);
  int N, K;
  cin >> N >> K;
  vector<ll> a(N);
  for (int i = 0; i < N; i++)
    cin >> a[i];
  ll ans = INF;
  for (int bit = 0; bit < (1 << N); bit++)
  {
    ll cost = 0;
    ll tmpHeight = a[0];
    vector<ll> b = a;
    for (int i = 1; i < N; i++)
    {
      if (bit & (1 << i))
      {
        if (a[i] <= tmpHeight)
        {
          b[i] = tmpHeight + 1;
          cost += b[i] - a[i];
          tmpHeight++;
        }
        else
        {
          b[i]++;
          cost++;
          tmpHeight = b[i];
        }
      }
      else
      {
        if (a[i] > tmpHeight)
          tmpHeight = a[i];
      }
    }
    int num = 1;
    ll nowHeight = a[0];
    for (int i = 1; i < N; i++)
    {
      if (b[i] > nowHeight)
      {
        nowHeight = b[i];
        num++;
      }
    }
    cout << num << endl;
    if (num >= K)
      ans = min(ans, cost);
  }
  return 0;
}

