int main()
{
  int N,K;
  cin >> N >> K;
  vector<ll> A(N);
  REP(i,N){
    cin >> A.at(i);
  }

  ll ans = LLONG_MAX;
  for(int i=0; i<(1<<N); i++){
    if(K > counter(i))continue;
    queue<int> idx;
    REP(j,N){
      if(i & (1<<j)){
        idx.push(j);
      }
    }
    bool flag = true;
    int a = idx.front();    
    ll st = A.at(idx.front());
    REP(j,a){
      if(st <= A.at(j)){
        flag = false;
        break;
      }
    }
    if(!flag)continue;

    idx.pop();
    ll cnt = 0;
    while(!idx.empty()){
      ll nx = A.at(idx.front());
      if(st >= nx){
        cnt += st-nx+1;
        st = st+1;
      }else{
        st = nx;
      }
      idx.pop();
    }
    ans = min(ans,cnt);
  }
  cout << ans << endl;
