	}
	if(s[a]>c)
	{
		dfs(a+1,b+1,s[a]);
	}
	else{
		dfs(a+1,b,c);
		cost+=(c+1-s[a]);
		dfs(a+1,b+1,c+1);
		cost-=(c+1-s[a]);
	}
}
