    i64 N,K;
    cin >> N >> K;
    vector<i64> a(N);
    rep(i,0,N) cin >> a[i];

    i64 ans=inf64;
    rep(b,0,1l<<N){
        i64 cost=0,height=0;
        vector<i64> h(N);
        rep(i,0,N){
            if(((b>>i)&1)==0 or height<a[i]){
                h[i]=a[i];
                chmax(height, a[i]);
                continue;
            }
            cost+=height-a[i]+1;
            height++;
            h[i]=height;
        }

        i64 cnt=0,maxi=0;
        rep(i,0,N){
            if(h[i]>maxi) ++cnt;
            chmax(maxi,h[i]);
        }

        if(cnt>=K) chmin(ans,cost);
    }

    cout << ans << endl;
}

