    static auto scan1_impl(istream& in) {
        using T = tuple_element_t<I,tuple<TS...>>;
        auto head = make_tuple(Scan1<T>::scan1(in));
        return tuple_cat(head, scan1_impl<I+1>(in));
    }
};

