void dfs(int num,int select){
	int mii = a[use[0]],sum = 0,aa[15],cnt = 0;
	for(int i = 0;i < n;i++) aa[i] = a[i];
	for(int i = 1;i < select;i++){
		mii = max(mii + 1,a[use[i]]);
		aa[use[i]] = mii;
		sum += mii - a[use[i]];
	}
	mii = 0;
	for(int i = 0;i < n;i++){
		if(aa[i] > mii) cnt++;
		mii = max(aa[i],mii);
	}
	if(cnt >= k) mi = min(mi,sum);
	if(select == k || num == n) return;
	dfs(num + 1,select);
	use[select] = num;
	dfs(num + 1,select + 1);
}

