tuple<VLL,VLL,VLL> my_dycstra(VVVLL &R,LL start, LL MOD = 0)
{
  LL N = R.size();
  LL INFINF = 1e15;
  priority_queue<VLL, VVLL, greater<VLL>> Q;
  VLL Cost(N, INFINF);
  VLL Path(N, -1);
  VLL Num(N, 0);
  Cost[start] = 0;
  Num[start] = 1;
  Q.push({0,start});
  while(!Q.empty()) {
    VLL q = Q.top();
    Q.pop();
    LL cost = q[0];
    LL from = q[1];

    if (Cost[from] < cost){continue;}
    //dump(from,cost);
    for(auto r : R[from]) {
      LL to = r[0];
      LL cost_to = r[1];
      //dump(to,cost_to);

      if(chmin(Cost[to], (cost + cost_to))) {
        Q.push({cost + cost_to, to});
        Path[to] = from;
        Num[to] = Num[from];
      }
      else if(Cost[to] == (cost + cost_to)){
        Num[to] += Num[from];
        if(MOD!=0){
          Num[to] %= MOD;
        }
      }
    }
  }
  // dump(C);
  return move(make_tuple(Cost,Path,Num));
}

