struct SegmentTree{
  VLL D;
  LL N;
  LL DEFAULT;
  string mode;

  void init(LL N,string mode = "min"){
    this->mode = mode;
    if(mode=="min"){
      DEFAULT = LONG_LONG_MAX;
    }
    else if(mode=="max"){
      DEFAULT = LONG_LONG_MIN;
    }
    else if(mode=="sum"){
      DEFAULT = 0LL;
    }
    else{
      this->mode="min";
      DEFAULT = LONG_LONG_MAX;
    }
    //this->N=N;
    LL K=1;
    while(K<N){
      K*=2;
    }
    this->N = K;
    this->D.resize(2*this->N,DEFAULT);
    dump(D.size());
  }
  SegmentTree(LL N,string mode = "min"){
    init(N,mode);      
  }
  SegmentTree(VLL &A,string mode = "min"){
    LL N = A.size();
    this->init(N,mode);
    dump(D.size());
    REP(i,N){
      dump(i,A[i]);
      set(i,A[i]);
    }
    dump(N);
    build();
  }
  void set(LL i, LL x){
    D[i+N] = x;
  }
  void build(){
    for(LL i=N-1;i>0;i--){
      if(mode=="min"){
        D[i] = min({D[2*i],D[2*i+1]});
      }
      else if(mode=="max"){
        D[i] = max({D[2*i],D[2*i+1]});
      }
      else if(mode=="sum"){
        D[i] = D[2*i]+D[2*i+1];
      }
    }
  }
  void update(LL i, LL x){
    D[i+N] = x;
    LL j = i+N;
    while(j>1){
      LL k = j/2;
      if(mode=="min"){
        chmin(D[k],D[j]);
      }
      else if(mode=="max"){
        chmax(D[k],D[j]);
      }
      else if(mode=="sum"){
        D[k] += D[j];
      }
      j=k;
    }    
  }
  void print(){
    dump(D);
    REPM(i,2*N,1){
      cerr << D[i] << " ";
      if(__builtin_popcountll(i+1)==1){
        cerr << endl;
      }
    }
  }
  LL query(LL a ,LL b, LL k=1, LL l=0 ,LL r=-1){
    if(r==-1){
      r = N;
    }
    if(b<=l || r <= a ){ return DEFAULT;}
    if(a<=l && r <= b ){ return D[k];}
    LL vl = query(a,b, 2*k  , l ,(l+r)/2);
    LL vr = query(a,b, 2*k+1, (l+r)/2,r);
    //dump(vl,vr);
    if(mode=="min"){
      return min({vl,vr});    
    }
    else if(mode=="max"){
      return max({vl,vr});    
    }
    else if(mode=="sum"){
      return vl+vr;    
    }
  }
};

