string rec(LL n,LL k, VLL &C){
  if(k==0){
    if(n==0){
      return "A";
    }
    if(n==1){
      return "B";
    }    
    return "C";
  }

  if(n==0){
    return "A";
  }
  n -=1;
  if(n>=0 and n<C[k-1]){
    return rec(n,k-1,C);
  }
  n -= C[k-1];
  if(n==0){
    return "B";
  }
  n -=1;
  if(n>=0 and n<C[k-1]){
    return rec(n,k-1,C);
  }
  n -= C[k-1];
  if(n==0){
    return "C";
  }
  dump("error");
  return "-";
}


