    }else if(N - now == K - increase_buildings){
        return max(0l, back_building_height + 1 - buildings[now]) + build(now + 1, max(back_building_height + 1, buildings[now]), increase_buildings + 1);
    }else{
        return min(max(0l, back_building_height + 1 - buildings[now]) + build(now + 1, max(back_building_height + 1, buildings[now]), increase_buildings + 1), build(now + 1, back_building_height, increase_buildings));
    }
}

int main(){
    cin >> N >> K;
    buildings.resize(N);
    for(int i = 0; i < N; i++){
        cin >> buildings[i];
    }
    cout << build(1, buildings[0], 1) << endl;
}

