Int N, K;
vector<Int> A;
#define INFTY 9223372036854775807

void input() {
  cin >> N >> K;
  Int a;
  rep(N) {
    cin >> a;
    A.push_back(a);
  }
}

Int dfs(Int n = 0, Int k = 0, Int cost = 0, Int max_h = 0) {
  if (n == N) {
    if (k >= K) return cost; // Kを満たしている場合はそれまでにかかった総コスト
    else return INFTY; // K満たしていないので無駄コスト
  }

  if (n == 0) {
    return dfs(1, 1, 0, A.at(0));
  }

  Int h = A.at(n);
  bool highest = max_h < h; // これまでで過去最高の高さ（=修正不要）

  // この建物の高さを前のよりも高くする or しないのbit全探索
  Int min_ = dfs(n+1, k + highest, cost, max(max_h, h));

  if (!highest) {
    cost += max_h + 1 - h; // これまでの最高+1の高さが必要
    Int yes = dfs(n+1, k+1, cost, max_h + 1);
    min_ = min(min_, yes);
  }

  return min_;
}

void solve() {
  cout << dfs() << endl;
}

int main() {
  input();
  solve();
  return 0;
}

