typedef long long ll;

int main(){
  int N, K; cin >> N >> K;
  vector<int> a(N);
  for(int i = 0; i < N; i++){
    cin >> a[i];
  }
  int number = 1;
  for(int i = 1; i < N; i++){
    bool ok = true;
    for(int j = 0; j < i; j++){
      if(a[j] >= a[i]) ok = false;
    }
    if(ok) number++;
  }
  if(number >= K){
    cout << 0 << endl;
    return 0;
  }
  number = K - number;
  ll ans = 1LL << 60;
  for(int i = 0; i < (1 << (N - 1)); i++){
    bitset<16> bit(i);
    if(bit.count() != number) continue;
    ll ans1 = 0;
    ll bound = a[0];
    for(int i = 0; i < N - 1; i++){
      if(bit[i]){
        if(bound >= a[i + 1]){
          ans1 += bound - a[i + 1] + 1;
          bound++;
        }
      }
    }
    ans = min(ans, ans1);
  }
  cout << ans << endl;
}

