const int INF = 1001001001;

int next_combination(int sub) {
    int x = sub & -sub, y = sub + x;
    return (((sub & ~y) / x) >> 1) | y;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);

    int n, k;
    cin >> n >> k;
    vector<int> a(n);
    rep(i, n) cin >> a[i];

    int seen = 0;
    int h = 0;
    rep(i, n) {
        if (a[i] > h) {
            seen++;
            h = a[i];
        }
    }

    if (seen >= k) {
        cout << 0 << endl;
        return 0;
    }

    int price_min = INF;
    for (int bit = (1<<k-seen)-1 ;bit < (1<<n-1); bit = next_combination(bit)) {
        int now_h = a[0];
        int price_cur = 0;
        bool ng = false;
        rep(i, n-1) {
            if (bit>>i&1) {
                if (now_h >= a[i+1]) {
                    price_cur += now_h - a[i+1] + 1;
                    now_h++;
                } else {
                    ng = true;
                    break;
                }
            }
            chmax(now_h, a[i+1]);
        }
        if (!ng) chmin(price_min, price_cur);
    }

    cout << price_min << endl;
}

