    for (int i = 1; i < n; ++ i) {
        if (vis[i]) {
            if (x[i] <= pre) {
                cnt += pre+1 - x[i];
                pre ++;
            } else {
                pre = x[i];
            }
        } else {
            if (x[i] > pre)
                pre = x[i];
        }
    }
    if (cnt < ans)
        ans = cnt;
}

