// 階乗 (mod とりバージョン)
ll fact_mod(ll n, ll mod) {
    ll f = 1; for (int i = 2; i <= n; i++) f = f * (i % mod) % mod;
    return f;
}

// 繰り返し二乗法 (modの世界での累乗)
// ※modが素数の場合、この関数で(mod - 2)乗したら、mod割り算ができるよ！
// (参考問題: ABC034 C問題など)
ll pow_mod(ll x, ll n, ll mod) {
    ll res = 1;
    while (n > 0) {
        if (n & 1) res = (res * x) % mod; //ビット演算(最下位ビットが1のとき)
        x = (x * x) % mod;
        n >>= 1; //右シフト(n = n >> 1)
    }
    return res;
}

// 組み合わせ nCr を求める (modあり)
ll comb_mod(ll n, ll r, ll mod) {
    if (r > n - r) r = n - r;
    if (r == 0) return 1;
    ll a = 1;
    for (int i = 0; i < r; i++) a = a * ((n - i) % mod) % mod;
    ll b = pow_mod(fact_mod(r, mod), mod - 2, mod);
    return (a % mod) * (b % mod) % mod;
}

int N, K;
vector<ll> a;

ll f(int bit) {
    ll cost = 0;

    //bit = 100101010101に対応する建物を建てるコストを求める

    vector<ll> b;

    for (int i = 0; i < N; i++) {
        if(!(bit & (1 << i))) continue;



        b.push_back(a[i]);
    }

    for (int i = 0; i < b.size() - 1; i++) {
        ll tmp_cost = max((ll)0, b[i + 1] - b[i]);
        b[i + 1] += tmp_cost;

        cost += tmp_cost;
    }

    return cost;
}

ll solve() {
    ll ans = 0;

    for (int bit = 0; bit < (1 << K); bit++) {
        bitset<32> tmp(bit);
        if (tmp.count() < K) continue;
        ans = max(ans, f(bit));
    }

    return ans; 
}

