    for(int i = 0;i < n;i++)cin >> a[i];

    for(int i = 0;i < (1 << n);i++){
        if(__builtin_popcount(i) != k)continue;

        int count = 0;
        int last = a[0];
        for(int j = 0;j < n;j++){
            if(j == 0)continue;

            if(i & (1 << j)){
                if(last < a[j]){
                    last = max(a[j],last);
