  }

  // i番目までで最も高いもの
  vector<ll> height(N);
  height[0] = 0;
  height[1] = a[0];

  ll SUBMAX = a[0];
  for (int i = 1; i < N; i++) {
    if (a[i] > SUBMAX) {
      height[i] = a[i-1];
    } else {
      height[i] = SUBMAX;
    }
