          temp++;
        } else {
          temp = height[i]+1;
        }

        // cost の計算
        if (i == 0) {
          temp = a[0];
          continue;
        }
        if (a[i] > temp) {
           temp = a[i];
           continue;
        }
        cost += temp -a[i];
      }
    }

