bool check(ll bit, vl &arr){
    ll seen = 1; //すでに見えているビルのbit列
    ll s = arr[0];
    FOR(i, 1, N){
        if(s < arr[i]){
            seen += 1<<i;
            s = arr[i];
        }
    }
    if((bit & seen) == seen){
        return true;
    }
    return false; 
}

