using namespace std;

int bitcount(int a){
	int r = 0;
	while(a){
		a -= a & -a;
		r++;
	}
	return r;
}

int main(){
	int n, k;
	cin >> n >> k;
	int a[n];
	for(int i = 0; i < n; i++) cin >> a[i];
	int ans = 1e9 + 7;
	for(int i = 0; i < 1 << n; i++){
		if(bitcount(i) < k) continue;
		int tmp = 0, p = -1;
		for(int j = 0; j < n; j++){
			if(i >> j & 1){
				if(p == -1) p = a[j] + 1;
				else{
					tmp += max(0, p - a[j]);
					p = max(p + 1, a[j] + 1);
				}
			}else p = max(p, a[j] + 1);
		}
		ans = min(ans, tmp);
		next:;
	}
	cout << ans << endl;
}

