  cin >> n >> k;
  rep(i,n) cin >> a[i];
  r[0] = 0;
  for(int i=1; i<n; i++) r[i] = max(r[i-1], a[i-1]);

  vector<int> c;
  c.reserve(n);
  cout << dfs(c) << endl;
}

