typedef long long ll;

int popcount(int n)
{
    int ans = 0;
    while (n > 0)
    {
        ans += n & 1;
        n >>= 1;
    }
    return ans;
}

ll get_cost(const vector<ll> &vs, const int bitmap)
{
    ll sum = 0;
    ll prev = vs[0];
    for (int i = 1; i < vs.size(); i++)
    {
        ll val = vs[i];
        if (((1 << i) & bitmap) != 0)
        {
            sum += max<ll>(0, prev + 1 - val);
            val = max<ll>(prev + 1, val);
        }
        prev = max(prev, val);
    }
    return sum;
}

