#include "bits/stdc++.h"
using namespace std;
const int N = 16;
const long long inf = 1e15 + 15;
int n , k;
int arr[N];
long long solve(int pos , int mask , int done){
	if(done >= k){
		return 0;
	}
	if(pos > n){
		return inf;
	}
	long long res = inf;
	res = min(res , solve(pos + 1 , mask , done));
	int last = arr[1];
	for(int i = 2 ; i < pos ; ++i){
		last = max(last , arr[i]);
		if((mask >> i) & 1){
			last = max(arr[i] , last + 1);
		}
	}
	res = min(res , solve(pos + 1 , mask | (1 << pos) , done + 1) + max(0 , last + 1 - arr[pos]));
	return res;
}
int main(){
	scanf("%d %d" , &n , &k);
	for(int i = 1 ; i <= n ; ++i){
		scanf("%d" , arr + i);
	}
	printf("%lld\n" , solve(2 , 1 << 1 , 1));
}

