int main()
{
	int n, k; cin >> n >> k;
	vector<int>a(n);
	for (int i = 0; i < n; i++) {
		cin >> a[i];
	}

	long long ans = 0;

	vector<int>see(n);
	int minH = a[0];
	int cnt = 1;
	for (int i = 0; i < n; i++){
		if (minH < a[i]) {
			minH = a[i];
			cnt++;
		}
		see[i] = minH;
	}

	while (cnt > k) {
		int index = 0;
		vector<pair<int, int>>b;
		for (int i = 0; i < n- 1; i++) {
			if (see[i] < see[i + 1]) {
				b.push_back(make_pair(see[i + 1] - see[i], index));
				index = i + 1;
			}
		}
		sort(b.begin(), b.end());
		a[b[0].second] += b[0].first;
		ans += b[0].first;

		int minH = a[0];
		cnt = 1;
		for (int i = 0; i < n; i++) {
			if (minH < a[i]) {
				minH = a[i];
				cnt++;
			}
			see[i] = minH;
		}
	}

	while (cnt < k) {
		vector<pair<int, int>>b;
		for (int i = n - 1; i > 0; i--) {
			if (see[i] == see[i - 1]) {
				b.push_back(make_pair(see[i] + 1 - a[i], n - i));
			}
		}
		sort(b.begin(), b.end());
		a[n-b[0].second] += b[0].first;
		ans += b[0].first;

		int minH = a[0];
		cnt = 1;
		for (int i = 0; i < n; i++) {
			if (minH < a[i]) {
				minH = a[i];
				cnt++;
			}
			see[i] = minH;
		}
	}

	cout << ans << endl;

    return 0;
}

