using namespace std;

int N, K, i, j, ans;
int *ptr;
int a[16], a_[16], c[16];

void solve(int cn, int an)
{
    if (K == cn)
    {

        for (j = 0; j < N; j++)
            a_[j] = a[j];

        int tmp = 0;

        for (i = 1; i < K; i++)
        {

            j = c[i] - 1;
            int tmpMax = a_[j];
            while (j > c[i - 1])
            {
                j--;

                if (tmpMax < a_[j])
                    tmpMax = a_[j];
            }

            if (a_[c[i]] <= a_[j])
            {
                tmp += a_[j] + 1 - a_[c[i]];
                a_[c[i]] = a_[j] + 1;
            }
        }

        if (tmp < *ptr)
            *ptr = tmp;

        return;
    }

    if (N <= an)
        return;

    c[cn] = an;
    solve(cn + 1, an + 1);

    solve(cn, an + 1);

    return;
}

int main()
{

    cin >> N >> K;
    for (i = 0; i < N; i++)
        cin >> a[i];

    if (N == K)
    {
        ans = 0;
        for (i = 1; i < N; i++)
        {
            if (a[i] <= a[i - 1])
            {
                ans += a[i - 1] + 1 - a[i];
                a[i] = a[i - 1] + 1;
            }
        }
    }
    else
    {
        ptr = &ans;
        *ptr = 2000000000;
        c[0] = 0;
        solve(1, 1);
    }

    cout << ans << endl;

    return 0;
}

