        int l = id[0], r = id[id.size()-1];

        ll mi = 0;
        int idx = 0;
        for(int i=0; i<=l; i++){
            mi = max(mi, tmp[i]);
        }
        // 0~lより大きくある必要
        ll cnt = 0;
        for(int i=0; i<id.size(); i++){
            if(tmp[id[i]] < mi){
                cnt += mi - tmp[id[i]];
                tmp[id[i]] = mi;
            }
        }
        // [l,r]を考える
        idx = 0;
        for(int i=l; i<=r; ++i){
            if(id[idx] == i){

                idx++;
                ll mx = 0;
                for(int j=0; j<i; j++){
                    mx = max(mx, tmp[j]);
                }

                if(tmp[i] > mx) continue;
                else{
