int main() {
    int n, k;
    cin >> n >> k;
    vi a(n);
    rep(i, n) cin >> a[i];

    stack<Bit> s;
    s.push({1, k - 1, n - k});

    int ans = INF;

    while (!s.empty()) {
        Bit t = s.top(); s.pop();

        if (t.t == 0 && t.f == 0) {
            vi h(n);
            h[0] = a[0];
            rep(i, 1, n)
                h[i] = max(h[i - 1], a[i]);

