                if (bit(t.b, n - 1 - i) && a[i] <= h[i - 1]) {
                    h[i] = h[i - 1] + 1;
                    cost += h[i] - a[i];
                }
            }

            umin(ans, cost);

            continue;
        }

        if (t.t > 0)
            s.push({(t.b << 1) + 1, t.t - 1, t.f});

        if (t.f > 0)
            s.push({t.b << 1, t.t, t.f - 1});
    };

    cout << ans << endl;

    return 0;
}

