int main(){
    int N, K, upper;
    ll ans, tmp, pre;
    cin >> N >> K;
    if (K == 1) {
        cout << 0 << '\n';
        return 0;
    }
    vector<ll> building(N);
    for (int i = 0; i < N; i++) cin >> building[i];

    upper = pow(2, N);
    ans = INF;
    for (int b = 0; b < upper; b++) {
        bitset<MAX> bs(b);
        vector<int> v(MAX, 0);
        if (bs.count() != K-1) continue;
        for (int i = 0; i < N; i++)
            if ((bs >> i)[0]) v[i] = 1;
        tmp = 0;
        pre = building[0];
        for (int i = 0; i < N-1; i++) {
            if (v[i]) {
                if (pre >= building[i+1]) {
                    tmp += pre - building[i+1] + 1;
                    pre = max(pre+1, building[i+1]);
                }
            }
            pre = max(pre, building[i+1]);
        }
        ans = min(ans, tmp);
    }
    cout << ans << '\n';
}

