int n,k;
int a[15];
int r[15];

int cost(vector<int> &c) {
  assert(c.size() == k);
  int s = 0;
  int p=0;
  for(int i=0; i<k; i++) {
    s += max(0, (r[c[i]]+1+p) - a[c[i]]);
    if((r[c[i]]+1+p) - a[c[i]] > 0) p++;
    else p = 0;
  }
  return s;
}

int dfs(vector<int> &c, int index=0) {
  if(c.size() == k) return cost(c);
  int rest = n-index;
  int s = 1e9+15;
  if(c.size()+rest < k) return s;
  s = min(s, dfs(c, index+1));
  c.push_back(index);
  s = min(s, dfs(c, index+1));
  c.pop_back();
  return s;
}

