int calc(int n, int k, const vector<ll> &p) {
    ll m = LLONG_MAX;
    for(ll i = 0; i < (1LL << n); i++) {
       // cout << b << endl;
       int num = 0;
       ll cost = 0;
       ll h = 0;
       for(int j = 0; j < n; j++) {
           if(h < p[j]) {
               h = p[j];
               num++;
           } else if((i >> j) & 1) {
               h++;
               cost += h - p[j];
               num++;
           }
        }
        if(num < k) continue;
        m = min(m, cost);
    }
    return m;
}

int main() {
    int N, K;
    cin >> N >> K;
    vector<ll> A(N);
    for(auto &x: A) cin >> x;
    cout << calc(N, K, A) << endl;
    return 0;
}

