void Dfs(ll u)
{
    if(u==n+1)
    {
        ll b[20];
        ll cnt=0;
        ll pre=a[1];
        for(ll i=1;i<=n;i++)if(vis[i]==1)cnt++;
        for(ll i=1;i<=n;i++)b[i]=a[i];
        if(cnt==k)
        {
            ll sum=0;
            for(ll i=2;i<=n;i++)
            {
                if(vis[i]==1)
                {
                    if(b[i]>pre)pre=b[i];
                    else
                    {
                        sum+=pre+1-b[i];
                        b[i]=pre+1;
                        pre=b[i];
                    }
                }
            }
            ll look=1;
            for(ll i=2;i<=n;i++)
            {
                ll flag=0;
                for(ll j=1;j<i;j++)
                {
                    if(b[j]>b[i])flag=1;
                }
                if(flag==0)look++;
            }
            if(look==k)
            {
                output=min(output,sum);
            }
        }
        return ;
    }
    vis[u]=1;
    Dfs(u+1);
    if(u!=1)
    {
        vis[u]=0;
        Dfs(u+1);
    }
}
