int popcount(ll n) {
  int ret = 0;
  while (n > 0) {
    if (n & 1) ret++;
    n >>= 1;
  }
  return ret;
}

// 要考慮
// - 最初からk色以上見えてる場合

void solve() {
  ll n, k; cin >> n >> k;
  vector<ll> a(n); rep(i, n) cin >> a[i];
  vector<ll> b(n);

  ll ans = INF;
  rep(i, 1<<n) {
    // 一番左の人を見えなくするのは無理
    if ((i & 1) == 0) continue;

    // k色見えないのでダメ
    if (popcount(i) < k) continue;

    copy(all(a), b.begin());
    ll maxh = b[0], view = 1, cost = 0;
    bool ok = true;
    for (int j = 1; j < n; j++) {
      // 今見てる建物を見えるようにすべきか
      bool b1 = ((i >> j) & 1) == 1;
      // 今見てる建物は左から見えるのか
      bool b2 = b[j] > maxh;

      if (b1 && b2) {
        // もう見えてるのでOK
        view++;
      } else if (b1 && !b2) {
        // 見えるようにする
        cost += maxh + 1 - b[j];
        b[j] = maxh + 1;
        view++;
      } else if (!b1 && b2) {
        // 見せたくないのに見えてる
        // 前の建物を高くするよりないけど無駄なのでスキップ
        ok = false;
        break;
      } else {
        // 見せたくないし、見えてないからOK
      }

      maxh = max(maxh, b[j]);
    }

    if (!ok) continue;

    // debug3(i, view, cost);

    ans = min(ans, cost);
  }
  outl(ans);
}

signed main() {
  cin.tie(0);
  ios::sync_with_stdio(false);
  srand((unsigned)time(NULL));
  fix(12);

  solve();
}

