int main() {
	ll N;
	cin >> N;
	ll K;
	cin >> K;
	vector<ll> A(N);
	rep(i, N) {
		cin >> A[i];
	}

	ll result = INF;

	vector<bool> flag(N, false);
	rep(i, (1 << (N - 1))) {
		ll k = i;
		ll count = 0;
		rep(j, N - 1) {
			if ((k & 1) > 0) {
				flag[j + 1] = true;
				count++;
			}
			else {
				flag[j + 1] = false;
			}
			k >>= 1;
		}

		ll see = 1;
		ll highest = A[0];
		ll cost = 0;

		reps(j, 1, N - 1) {
			if (highest < A[j]) {
				highest = A[j];
				see++;
			}
			else {
				if (flag[j]) {
					highest++;
					cost += highest - A[j];
					see++;
				}
			}
		}

		if (see >= K) {
			chmin(result, cost);
		}
	}

	cout << result << endl;

	return 0;
}



