using namespace std;
int n,k;
long long s[20];
long long sum,cost;
void dfs(long long a,long long b,long long c)
{
	if(a==n)
	{
		if(b>=k)
		sum=min(sum,cost);
		return;
	}
	if(s[a]>c)
	{
		dfs(a+1,b+1,s[a]);
	}
	else{
		dfs(a+1,b,c);
		cost+=(c+1-s[a]);
		dfs(a+1,b+1,c+1);
		cost-=(c+1-s[a]);
	}
}
int main(){
	while(scanf("%d%d",&n,&k)==2)
	{
		sum=0x3f3f3f3f;
		for(int i=0;i<n;i++)
		scanf("%lld",&s[i]);
		dfs(1,1,s[0]); 
		printf("%lld\n",sum);
	}
	return 0;
}

