struct UnionFindTree {
private:
  vector<LL> UFT;
public:
  UnionFindTree(LL N) {
    UFT.resize(N);
    for (LL i = 0; i < N; i++) {
      UFT[i] = -1; 
    }
  }

  //! rootのindexを返す
  LL root(LL i) { 
    if (UFT[i] < 0) {
      return i;
    }
    else {
      LL j = root(UFT[i]);
      UFT[i] = j;
      return j;
    }
  }

  //! iとjが同じ集合かどうか
  bool same(LL i, LL j) {
    return (root(i) == root(j));
  }
  //! 統合する
  bool unite(LL i, LL j)
  {
    if(same(i,j)){
      return false;
    }

    LL root_i = root(i);
    LL root_j = root(j);
    if (root_i != root_j) {
      if (size(root_i) < size(root_j)) {
        swap(root_i, root_j);
      }
      UFT[root_i] += UFT[root_j];
      UFT[root_j] = root_i;
    }
    return true;
  }

  //! 自身が属している集合のサイズを返す 
  LL size(LL i) {
    return -UFT[root(i)];
  }

  //! 集合が何個あるかを返す
  LL get_root_num() {
    set<LL> roots;
    for (LL i = 0; i < (LL)UFT.size(); ++i) {
      roots.insert(root(i));
    }
    return (LL)roots.size();
  }

  //! 各rootに属する子を返す 
  map<LL, vector<LL>> get_root_child() {
    map<LL, vector<LL>> a;
    for (LL i = 0; i < (LL)UFT.size(); ++i) {
      LL j = root(i);
      a[j].push_back(i);
    }
    return move(a);
  }
  //! 各rootに属する子を返す 
  unordered_map<LL, vector<LL>> get_root_child2() {
    unordered_map<LL, vector<LL>> a;
    for (LL i = 0; i < (LL)UFT.size(); ++i) {
      LL j = root(i);
      a[j].push_back(i);
    }
    return move(a);
  }

  //! 標準エラーに出力する
  void print() { 
    map<LL, vector<LL>> M = get_root_child();
    for(auto m :M){
      dump(m.first, m.second);
    }
    // for (LL i = 0; i < (LL)UFT.size(); ++i) {
    //   cerr << root(i) << " ";

    // }
    cerr << endl;
  }
};
