tuple<VLD,VLL,VLL> my_dycstra_v1(vector<vector<pair<LL,LD>>> &R,LL start, LL MOD = 0)
{
  LL N = R.size();
  LL INFINF = 1e15;
  using PQ = pair<LD,LL>;
  priority_queue<PQ, vector<PQ>, greater<PQ>> Q;
  VLD Cost(N, INFINF);
  VLL Path(N, -1);
  VLL Num(N, 0);
  Cost[start] = 0;
  Num[start] = 1;
  Q.push({0,start});
  LL cnt=0;
  while(!Q.empty()) {
    //dump(Q.size());
    PQ q = Q.top();
    Q.pop();
    LD cost = q.first;
    LL from = q.second;

    if (Cost[from] < cost){continue;}

    //dump(from,cost);
    for(auto r : R[from]) {
      cnt++;
      LL to = r.first;
      LD cost_to = r.second;
      //dump(to,cost_to);

      if(chmin(Cost[to], (cost + cost_to))) {
        Q.push({cost + cost_to, to});
        Path[to] = from;
        Num[to] = Num[from];
      }
      else if(Cost[to] == (cost + cost_to)){
        Num[to] += Num[from];
        if(MOD!=0){
          Num[to] %= MOD;
        }
      }
    }
  }
  dump(cnt);
  // dump(C);
  return move(make_tuple(Cost,Path,Num));
}



