//見える高さを計算
LL f(vector<LL>& v){
	LL max = v[0];
	LL ans = 1;
	int size = v.size();
	for(int i=1;i<size;++i){
		if( max < v[i] ){
			++ans;
			max = v[i];
		}
	}
	return ans;
}

//posを見えるようにするためのコスト
pair<LL,LL> cost(vector<LL>& v,int pos){
	LL ans = 0;
	LL add = 0;
	LL MAX = 0;
	int size = v.size();
	vector<bool> hi(size,false);
	hi[0] = true;
	MAX = v[0];
	for(int i=1;i<size;++i){
		if( MAX < v[i] ){
			hi[i] = true;
			MAX = v[i];
		}
	}

	//posより前の最大値
	MAX = 0;
	for(int i=0;i<pos;++i){
		MAX = max(MAX,v[i]);
	}
	if( MAX >= v[pos] ){
		add = MAX -v[pos] + 1;
		ans = MAX -v[pos] + 1;
	}

	MAX = v[pos];
	for(int i=pos+1;i<size;++i){
		if( hi[i] ){
			if( MAX < v[i] ){
				break;
			}else{
				ans += MAX-v[i]+1;
			}
		}
	}
	pair<LL,LL> res(ans,add);
	return res;
}
void solve(){
	int N,K;
	cin >> N >> K;
	vector<LL> A(N);
	vector<LL> diff(N,0);
	for(int i=0;i<N;++i){
		cin >> A[i];
		if( i ){
			diff[i] = A[i]-A[i-1];
		}
	}

	LL ans = 0;
	pair<LL,LL> MIN,temp;
	while( f(A) < K ){
		MIN.first = LINF;
		int pos = -1;
		for(int i=N-1;i>0;--i){
			temp = cost(A,i);
			if( temp.first > 0 && temp.first < MIN.first){
				MIN = temp;
				pos = i;
			}
		}
		A[pos] += MIN.second;
		ans += MIN.second;
	}
	cout << ans << endl;
}

