void comb(int n, int k, ll cost, ll heighest, const vector<ll> &a, vector<int> visible = {0}) {
    if (visible.size() == k) {
        min_cost = min(min_cost, cost);
        return;
    }
    int last = visible.back();
    for (int i = last + 1; i < n; i++) {
        vector<int> tmp = visible;
        tmp.push_back(i);
        comb(n, k, cost + (heighest - a[i] + 1), heighest + 1, a, tmp);
        heighest = max(heighest, a[i]);
    }
}

