    for(int bit=0; bit<(1<<n); ++bit){
        vector<int> tmp(0);
        int cnt;
        int ans_tmp=0;
        bitCount(bit, cnt, tmp);
        if(cnt<k)continue;
        int nmax=a[0];
        for(int i:tmp){
            if(i==0) continue;
            if(a[i]<nmax){ans_tmp += (nmax-a[i]+1); nmax++;}
            else nmax=a[i];
        }
        ans=min(ans,ans_tmp);
    }

    // output
    cout << ans << endl;
    return 0;
}

