ll change_temp(ll s, ll t, ll p, ll q)
{
    ll temp = 0;
    if (p <= q)
    {
        if (p > 0)
            temp = -s * (q - p);
        else if (q < 0)
            temp = -t * (q - p);
        else
            temp = t * p - s * q;
    }
    else
    {
        if (q > 0)
            temp = s * (p - q);
        else if (p < 0)
            temp = t * (p - q);
        else
            temp = s * p - t * q;
    }

    return temp;
}

