ll c(const vector<ll> &p, const bitset<15> &b) {
    ll h = p[0];
    ll res = 0;
    for (int i = 1; i < p.size(); i++)
    {
        if (b[i] == true)
        {
            if (p[i] <= h)
            {
                res += h - p[i] + 1;
                h++;
            }
        }
        h = max(h, p[i]);
    }
    return res;
}

int calc(int n, int k, const vector<ll> &p) {
    ll m = LLONG_MAX;
    for(ll i = (1LL << k - 1); i < (1LL << n); i++) {
        if(__builtin_popcount(i) < k) continue;
        bitset<15> b(i);
       // cout << b << endl;
        m = min(m, c(p, b));
    }
    return m;
}

