void dfs(int num,int h){
	if(num == n){
		int sum = 0,ma = 0,cnt = 0;
		for(int i = 0;i < n;i++){
			if(ma < aa[i]) cnt++;
			ma = max(ma,aa[i]);
			sum += max(0ll,aa[i] - a[i]);
		}
		if(cnt >= k) mi = min(mi,sum);
		return;
	}
	aa[num] = a[num];
	dfs(num + 1,max(h,aa[num]));
	aa[num] = max(h + 1,a[num]);
	dfs(num + 1,max(h,aa[num]));
}

