ll N, K, A[15], M[16], mincount=100000000000;

void dfs(ll id, ll k, vector<ll> v){
    if(k>K) return;
    if(id==N){
        if(k!=K) return;
        ll ms[N+1];
        ll count=0;
        for(ll i=0;i<N+1;i++) ms[i] = M[i];
        for(ll i=0;i<v.size();i++) {
            if(v[i]==1) {
                if(A[i]-ms[i]-1<0) {
                    count+= ms[i]+1-A[i];
                    for(ll j=i+1;j<N+1;j++) ms[j] = max(ms[i]+1, ms[j]);
                }
            }
        }
        mincount = min(mincount, count);
        /*
