#include <bits/stdc++.h>
using namespace std;
#define int long long
#define REP(i, n) FOR(i, 0, n)
#define REPR(i, n) for (int i = n - 1; i >= 0; i--)
#define FOR(i, s, n) for (int i = (s), i##_len = (n); i < i##_len; ++i)
#define ALL(obj) (obj).begin(), (obj).end()
#define ALLR(obj) (obj).rbegin(), (obj).rend()
#define DIV(a, b) ((a - 1) / b + 1)

template <typename T>
bool next_combination(const T first, const T last, int k) {
    const T subset = first + k;
    // empty container | k = 0 | k == n
    if (first == last || first == subset || last == subset) {
        return false;
    }
    T src = subset;
    while (first != src) {
        src--;
        if (*src < *(last - 1)) {
            T dest = subset;
            while (*src >= *dest) {
                dest++;
            }
            iter_swap(src, dest);
            rotate(src + 1, dest + 1, last);
            rotate(subset, subset + (last - dest) - 1, last);
            return true;
        }
    }
    // restore
    rotate(first, subset, last);
    return false;
}

signed main() {
    ios::sync_with_stdio(false);
    cin.tie(0);
    int N, K;
    cin >> N >> K;
    vector<int> A(N);
    REP(i, N) { cin >> A[i]; }
    int ans = 1e15;
    // 0番目の先頭は必ず見えるので、高さを変えない
    vector<int> L(N - 1);
    iota(ALL(L), 1LL);
    do {
        int sum = 0, before = A[0] + 1;
        vector<int> cp(K - 1);
        copy(L.begin(), L.begin() + K - 1, cp.begin());
        sort(ALL(cp));
        REP(i, K - 1) {
            if (A[cp[i]] >= before) {
                before = A[cp[i]];
            } else {
                sum += before - A[cp[i]];
                before++;
            }
        }
        ans = min(ans, sum);
    } while (next_combination(ALL(L), K - 1)); // 次の順列を生成

    cout << ans << endl;

    return 0;
}

