void solve(){
    int N, K;
    cin >> N >> K;
    vector<ll> bill(N);
    rep(i, N) cin >> bill[i];
    ll ans = lnf;
    // とりあえず高くする建物を決める
    // 高くした物がK個以上かを確認する
    int up_cnt;
    set<int> up_bill;
    ll ans_tmp;
    for (int bit = 0; bit < (1 << (N-1)); bit++){
        ans_tmp = 0;
        up_cnt = 1; // bill[0]は必ず見える
        up_bill ={};
        for (int i = 0; i < N-1; i++){
            if ((bit >> i) & 1){
                up_cnt++;
                up_bill.insert(i+1);
            }
        }

        if (up_cnt != K) continue;      // 見る個数が K 以外は除外

        ll now_high = bill[0];
        for (int i = 1; i < N; i++){
            if (up_bill.count(i)){  // bill[i] を見る時
                if (now_high > bill[i]){
                    // bill[i] の高さを上げる
                    ans_tmp += (now_high - bill[i] + 1);
                    now_high += 1;
                }else{
                    // あげなくて良いが，現在の高さを更新する．
                    now_high = max(bill[i], now_high);
                }
            }else{                  // 見るビルでない時
                now_high = max(now_high, bill[i]);
            }
        }
        ans = min(ans, ans_tmp);
    }
    cout << ans << endl;
}

