    int ans = 1e15;
    // 0番目の先頭は必ず見えるので、高さを変えない
    vector<int> L(N - 1);
    iota(ALL(L), 1LL);
    do {
        int sum = 0, before = A[0];
        vector<int> cp(K - 1);
        copy(L.begin(), L.begin() + K - 1, cp.begin());
        sort(ALL(cp));
        for (auto &x : cp) {
            if (A[x] > before) {
                before = A[x];
            } else {
                sum += before + 1LL - A[x];
                before++;
            }
        }
        ans = min(ans, sum);
    } while (next_combination(ALL(L), K - 1)); // 次の順列を生成

    cout << ans << endl;

    return 0;
}

