int arr[N];
long long solve(int pos , int len , int done){
	if(done >= k){
		return 0;
	}
	if(pos > n){
		return inf;
	}
	long long res = inf;
	res = min(res , solve(pos + 1 , max(len , arr[pos]) , done));
	int nlen = max(arr[pos] , len + 1);
	res = min(res , solve(pos + 1 , nlen , done + 1) + nlen - arr[pos]);
	return res;
}
