tuple<VLL,VLL,VLL> my_dycstra(VVVLL &R,LL start, LL MOD = 0)
{
  LL N = R.size();
  LL INFINF = 1e15;
  priority_queue<VLL, VVLL, greater<VLL>> Q;
  VLL Cost(N, INFINF);
  VLL Path(N, -1);
  VLL Num(N, 0);
  Cost[start] = 0;
  Num[start] = 1;
  Q.push({0,start});
  while(!Q.empty()) {
    VLL q = Q.top();
    Q.pop();
    LL cost = q[0];
    LL from = q[1];

    if (Cost[from] < cost){continue;}
    //dump(from,cost);
    for(auto r : R[from]) {
      LL to = r[0];
      LL cost_to = r[1];
      //dump(to,cost_to);

      if(chmin(Cost[to], (cost + cost_to))) {
        Q.push({cost + cost_to, to});
        Path[to] = from;
        Num[to] = Num[from];
      }
      else if(Cost[to] == (cost + cost_to)){
        Num[to] += Num[from];
        if(MOD!=0){
          Num[to] %= MOD;
        }
      }
    }
  }
  // dump(C);
  return move(make_tuple(Cost,Path,Num));
}

VLL haba_yuusen_kyori(VVLL &V, LL n ){
  LL N = V.size();
  VLL D(N,-1);
  queue<pair<LL,LL>> Q;
  Q.push({n,0});
  while(!Q.empty()){
    auto q = Q.front();
    Q.pop();
    LL no = q.first;
    LL d  = q.second;
    D[no] = d;
    for(auto v : V[no]){
      if(D[v]!=-1){
        continue;
      }
      D[v] = d+1;
      Q.push({v,d+1});
    }    
  }
  return move(D);  
}  

struct SegmentTree{
  VLL D;
  LL N;
  LL DEFAULT;
  string mode;

  void init(LL N,string mode = "min"){
    this->mode = mode;
    if(mode=="min"){
      DEFAULT = LONG_LONG_MAX;
    }
    else if(mode=="max"){
      DEFAULT = LONG_LONG_MIN;
    }
    else if(mode=="sum"){
      DEFAULT = 0LL;
    }
    else{
      this->mode="min";
      DEFAULT = LONG_LONG_MAX;
    }
    //this->N=N;
    LL K=1;
    while(K<N){
      K*=2;
    }
    this->N = K;
    this->D.resize(2*this->N,DEFAULT);
    dump(D.size());
  }
  SegmentTree(LL N,string mode = "min"){
    init(N,mode);      
  }
  SegmentTree(VLL &A,string mode = "min"){
    LL N = A.size();
    this->init(N,mode);
    dump(D.size());
    REP(i,N){
      dump(i,A[i]);
      set(i,A[i]);
    }
    dump(N);
    build();
  }
  void set(LL i, LL x){
    D[i+N] = x;
  }
  void build(){
    for(LL i=N-1;i>0;i--){
      if(mode=="min"){
        D[i] = min({D[2*i],D[2*i+1]});
      }
      else if(mode=="max"){
        D[i] = max({D[2*i],D[2*i+1]});
      }
      else if(mode=="sum"){
        D[i] = D[2*i]+D[2*i+1];
      }
    }
  }
  void update(LL i, LL x){
    D[i+N] = x;
    LL j = i+N;
    while(j>1){
      LL k = j/2;
      if(mode=="min"){
        chmin(D[k],D[j]);
      }
      else if(mode=="max"){
        chmax(D[k],D[j]);
      }
      else if(mode=="sum"){
        D[k] += D[j];
      }
      j=k;
    }    
  }
  void print(){
    dump(D);
    REPM(i,2*N,1){
      cerr << D[i] << " ";
      if(__builtin_popcountll(i+1)==1){
        cerr << endl;
      }
    }
  }
  LL query(LL a ,LL b, LL k=1, LL l=0 ,LL r=-1){
    if(r==-1){
      r = N;
    }
    if(b<=l || r <= a ){ return DEFAULT;}
    if(a<=l && r <= b ){ return D[k];}
    LL vl = query(a,b, 2*k  , l ,(l+r)/2);
    LL vr = query(a,b, 2*k+1, (l+r)/2,r);
    //dump(vl,vr);
    if(mode=="min"){
      return min({vl,vr});    
    }
    else if(mode=="max"){
      return max({vl,vr});    
    }
    else if(mode=="sum"){
      return vl+vr;    
    }
  }
};

