class mod_int{
public:
	int x;
	mod_int():x(0){}
	mod_int(int u):x(u){}
	mod_int operator=(int u){
		x=u;
		return *this;
	}
	mod_int operator+=(mod_int y){
		x+=y.x;
		x=x>=mod?x-mod:x;
		return *this;
	}
	mod_int operator-=(mod_int y){
		x-=y.x;
		x=x<0?x+mod:x;
		return *this;
	}
	mod_int operator*=(mod_int y){
		x*=y.x;
		x%=mod;
		return *this;
	}
	mod_int operator/=(mod_int y){
		mod_int z=1;
		for(int u=1;u<=mod-2;u<<=1){
			if((mod-2)&u)
				z*=y;
			y*=y;
		}
		operator*=(z);
		return *this;
	}
};
