        for(int i = 0; i < n; ++i) {
            if(bit & (1 << i)) {
                select.push_back(i);
            }
        }
        if((int)select.size()!= k) continue;
        vector<ll> tmpa = a;
        ll tmpans = 0;
        for(auto v : select) {
            ll height = tmpa[v];
            ll maxheihgt = 0;
            for(int i = 0; i < v; i++) {
                maxheihgt = max(maxheihgt,tmpa[i]); 
            }
            if(maxheihgt >= height) {
                ll add = maxheihgt - height + 1;
                tmpa[v] += add;
                tmpans += add;
            }
        }
        ans = min(ans,tmpans);
    }
    cout << ans << endl;
    return 0;
}

