void bit_search(ll n, ll k){

    for(ll bit = 0; bit < (1<<n); bit++){
        ll can_see = 0;
        vector<ll> build;
        vector<ll> test;
        for(ll i = 0; i < n; i++){
            if(bit & (1<<i)){
                can_see++;
                build.push_back(vec[i]);
                test.push_back(i);
            }
        }

        if(can_see >= k){
            if(test.size() > 0 && test[0] != 0){
                continue;
            }
            ll tmp = 0;
            ll now = 0;

            for(ll j = 0; j < build.size(); j++){
                if(j == 0){
                    now = build[j];
                    continue;
                }
                if(now >= build[j]){
                    tmp += now + 1 - build[j];
                    now = now + 1;
                }else{
                    now = build[j];
                }
            }

            ans = min(ans, tmp);
        }
    }
}

