using ull = unsigned long long;

int main() {
    size_t n = input();
    size_t k = input();
    vector<size_t> a(n, 0);
    a.reserve(n);
    for (size_t i = 0; i < n; ++i)
        a[i] = input();
    size_t money = numeric_limits<size_t>::max();
    for (size_t i = 0; i < (1ull << (n - 1)); ++i) {
        auto bit = (i << 1ull) | 1ull;
        size_t count = bitcount(bit);
        if (count < k)
            continue;
        size_t prev = a[0];
        size_t m = 0;
        for (size_t j = 0; j < n; ++j) {
            if (bit & (1ull << j)) {
                if (a[j] < prev) {
                    m += prev - a[j] + 1;
                    ++prev;
                    continue;
                }
            }
            prev = max(prev, a[j]);
        }
        money = min(money, m);
    }
    cout << money << endl;
    return 0;
}

