        this->num = num;
        this->flag_inf = flag_inf;
    }
    public:
    InfNum(): InfNum(0, 0){}
    InfNum(T num): InfNum(num, 0){}

    std::string toString(){
        if(flag_inf == 1){
            return std::string("+Inf");
        }else if(flag_inf == -1){
            return std::string("-Inf");
        }else{
            return std::to_string(this->num);
        }
    }

