    cout << 0 << endl;
    return 0;
  }

  size_t patternSize = k - index;
  ul ans = 1e19;
  for (int bit = 0; bit < (1 << n); ++bit) {
    // 最初に進めた分のインデックスに相当するビットは使わないので除外する
