      if (!(bit & (1 << i))) continue;
      if (a[i] < lastHeight) {
        total += (lastHeight - a[i]) + 1;
        ++lastHeight;
      } else if (a[i] == lastHeight) {
        ++total;
        lastHeight = a[i] + 1;
      } else {
        lastHeight = a[i];
      }
    }
    if (total == 0) continue;
    ans = min(ans, total);
