using namespace std;

int main()
{
    int n,k;
    cin >> n >> k;
    vector<pair<int,int>>V,v;
    vector<bool>F,f;
    V.resize(n);
    F.resize(n);
    int tmp = 0;
    for(int i = 0; i < n; i++)
    {
        cin >> V[i].first;
        if(tmp < V[i].first)
        {
            tmp = V[i].first;
            V[i].second = tmp;
            F[i] = true;
        }
        else
        {
            F[i] = false;
            V[i].second = tmp;
        }
    }
    //V[i] = {(建物iの高さ),(自分自身と自分よりも前の建物のうち高さの最大)}
    //F[i] = 建物iが見えればtrue、見えなければfalse
    //V[i].first >= V[i].second　かつ　V[i] = true　の時、建物iは見える

    int result = 0;
    for(int bit = 0; bit <(1<<n); bit++) //O(2^n)
    {
        v = V;
        f = F;
        int sum = 0;
        int count = 0;
        for(int i = 0; i < n; i++) //O(n)
        {
            if((bit&(1<<i))&&(f[i] == false))
            {
                sum += v[i].second + 1 - v[i].first;
                v[i].first = v[i].second + 1;
                v[i].second = v[i].first;
                f[i] = true;
                for(int j = i + 1; j < n; j++) //0(n) (ここまでO(n^7))
                {
                    if(v[j].first <= v[i].first)
                    {
                        f[j] = false;
                        v[j].second = v[i].first;
                    }
                }
            }
        }
        for(auto x:f)
        {
            if(x)
            {
                count++;
            }
        }
        if(count >= k)
        {
            if(result == 0)
            {
                result = sum;
            }
            else
            {
                result = min(result,sum);
            }
        }
    }
    cout << result << endl;
    return 0;
}

