      {
        count++;
        look[i]=true;
      }
    }

    nowH=a[0];
    for(int i=1;i<N;i++)
    {
      if(look[i]==true)
      {
        if(nowH>=a[i])
        {
          nowH++;
          yen+=nowH-a[i];
        }
        else nowH=a[i];
      }
      else if(look[i]==false&&nowH<a[i]) 
      {
        count=0;
        continue;
      }
    }
    //cout << count << endl;
    if(count>=K&&yen<ans) ans=yen;
  }

  cout << ans << endl;
  return 0;
}

