void dfs(int num,int select){
	if(select == k){
		int mii = a[use[0]],sum = 0;
		for(int i = 1;i < k;i++){
			mii = max(mii + 1,a[use[i]]);
			sum += mii - a[use[i]];
		}
		mi = min(mi,sum);
		return;
	}
	if(num == n) return;
	dfs(num + 1,select);
	use[select] = num;
	dfs(num + 1,select + 1);
}

