int main(){
    long n,k,max=0,ans=1e11;
    cin >> n >> k;
    vector<int> a(n),b(n);//b:i番もふくめ左側のmaxhの場所
    rep(i,n) cin >> a[i];
    rep(i,n){
        if(max<a[i]) max = a[i];
        b[i] = max;
    }
    rep(i,1<<n){
        long cost=0,cnt=0;
        bitset<15> s(i);
        vector<int> c=a,d=b;//maxh情報の初期化
        for(int j=0;j<n;j++){
            if(s.test(j)){
                cost += (d[j]-c[j])+1;//c[j]をd[j]+1に差し替える
                c[j] = d[j]+1;
                int k=j+1;
                while(c[k]<d[j]+1&&k<n){
                    d[k] = d[j]+1;
                    k++;
                }
            }
        }
        int max1 = 0;
        rep(j,n){
            if(max1<c[j]){
                max1 = c[j];
                cnt++;
            }
        }
        if(k <= cnt) ans = min(cost,ans);
    }
    cout << ans << endl;
}

