        tmp+=b[c[0]]+1-x[c[0]];
        x[c[0]]=b[c[0]]+1;
    }
    rep(i,0,c.size()-1){
      if(x[c[i]]+1>x[c[i+1]]){
        tmp+=x[c[i]]+1-x[c[i+1]];
        x[c[i+1]]=x[c[i]]+1;
      }
    }
    ans=min(tmp,ans);
  }
  out(ans);
}

