ll moddiv(ll n, ll a,ll m) {
	if (a == 0)return 1;
	if (a % 2 == 0) {
		ll b = moddiv(n, a / 2, m);
		return (b * b) % m;
	}
	else if (a % 2 == 1) return (n * moddiv(n, a - 1, m)) % m;
}

// グラフは<頂点,コスト>
void Dijkstra(ll v, vector<vector<pll>> graph,ll s, vl& ans) {
	auto comp = [](const pll a, const pll b) { return a.first > b.first; };
	priority_queue<pll, vector<pll>, decltype(comp)> que(comp);
	ans = vl(v, INF);
	ans[s] = 0;
	que.push(pll{ 0, s });
	pll a;
	while (!que.empty()) {
		ll c = que.top().first, p = que.top().second;
		que.pop();
		rep(i, graph[p].size()) {
			a = graph[p][i];
			if (ans[a.first] > a.second + c) {
				ans[a.first] = a.second + c;
				que.push(pll{ a.second + c,a.first });
			}
		}
	}
}

// 素数判定
bool judge(ll n) {
	for (ll i = 2; i * i <= n; i++) if (n %= i)return false;
	return true;
}

// 素因数分解
void factorization(ll n, vector<pll> &ans) {
	for (ll i = 2; i * i <= n; i++) {
		if (n % i == 0)ans.push_back(make_pair(i, 0));
		while (n % i == 0) {
			ans.back().second++;
			n /= i;
		}
	}
	if (n != 1) ans.push_back(make_pair(n, 1));
