int main() {

  int N, K;
  cin >> N >> K;

  vector<ll> a(N);

  for (int i = 0; i < N; i++) {
    cin >> a[i];
  }

  // i番目までで最も高いもの
  vector<ll> height(N);
  height[0] = 0;
  height[1] = a[0];

  ll SUBMAX = a[0];
  for (int i = 1; i < N; i++) {
    if (a[i] > SUBMAX) {
      height[i] = a[i-1];
    } else {
      height[i] = SUBMAX;
    }
  }



  ll ans = 10000000000000;

  // bit 全探索
  for (int bit = 0; bit < (1 << N); bit++) {
    ll color = 0;
    ll cost = 0;

    ll temp = 0; 
    for (int i = 0; i < N; i++) {

      if (!(bit & (1 << 0)) continue;

      if (bit & (1 << i)) {
        color++;

        // 次の建物に必要な最低限の高さを temp で現す
        if (temp >= height[i]) {
          temp++;
        } else {
          temp = height[i]+1;
        }

        // cost の計算
        if (i == 0) {
          temp = a[0];
          continue;
        }
        if (a[i] > temp) {
           temp = a[i];
           continue;
        }
        cost += temp -a[i];
      }
    }

    if (color >= K) chmin(ans, cost);

  }  

  cout << ans << endl;

}

