			if (i >> i2 & 1) {
				t.push_back(a[i2]);
				if (low >= a[i2]) { ok = false; break; }
			}
			else low = max(low, a[i2]);
		}
		if (!ok || t.size() != k)continue;
		rep(i2, 0, k - 1) {
			ll d = max(0ll, t[i2] + 1 - t[i2 + 1]);
			t[i2 + 1] += d;
			sum += d;
		}
		ans = min(sum, ans);
	}
