	ll maxi = 0;
	bool first = true;
	while (n) {
		if (n & 1) {
			if (first) {
				first = false;
				if (count!=0 && a[count] <= maxi) {
					//cout << "first " << a[count] << " maxi=" << maxi << endl;
					ret += maxi - a[count] + 1;
					vec.push_back(maxi + 1);
				}else vec.push_back(a[count]);
			}else vec.push_back(a[count]);
		}
		maxi = max(a[count], maxi);
		count++;
		n /= 2;
	}rep(i, vec.size()-1) {
		//cout << "a[i]=" << vec[i] << " a[i+1]=" << vec[i + 1] << endl;
		if (vec[i + 1] <= vec[i]) {
			ll temp = vec[i] - vec[i + 1] + 1;
			//cout << "temp=" << temp << endl;
