		}
		long long ans = 0;
		long long max_height = a[1];
		int cur_cnt = 1;
		if(b[cur_cnt]==1) cur_cnt++;
		for(int i=2;i<=n;i++){
			if(cur_cnt > cnt) break;
			if(i==b[cur_cnt]){
				if(max_height >= a[b[cur_cnt]]){
					ans+=max_height-a[b[cur_cnt]]+1;
					max_height++;
				} else {
					max_height = a[b[cur_cnt]];
				}
				cur_cnt++;
			} else {
				if(max_height < a[i]){
					max_height = a[i];
				}
			}
		}
		return ans;
	}
	res = min(res,f(x+1));
	b[++cnt] = x;
	res = min(res,f(x+1));
	cnt--;
	return res;
}
