	if(y==k)
	{
		if(sum>z)
		sum=z;
		return;
	}
	for(int i=x+1;i<n;i++)
	{
		int Max=0;
		int cnt=0;
		for(int k=x+1;k<i;k++)
		{
			if(s[k]>s[k-1])
			cnt++;
			else break;
		}
		for(int j=i-1;j>=0;j--)
		{
			if(s[j]>Max)
			Max=s[j];
		}
		if(Max>res)
		res=Max;
		if(s[i]>res)
		dfs(s[i],i,y+1+cnt,z);
		else dfs(res+1,i,y+1+cnt,z+res+1-s[i]);
	}
}
