int N, K;
ll a[15];

void solve()
{
    ll ans = LINF;
    int i = 0;
    while (i < (1 << N)) {
        if (popcount(i) != K) {
            i++;
            continue;
        }
        ll s = 0;
        ll prev = -1;
        REP (j, N) {
            if (i & (1 << j)) {
                if (prev != -1) {
                    ll d = a[j] - prev;
                    s += (d <= 0 ? -d+1 : 0);
                    prev = a[j] + (d <= 0 ? -d+1 : 0);
                } else {
                    prev = a[j];
                }
            } else {
                prev = max(prev, a[j]);
            }
        }
        ans = min(ans, s);
        i++;
    }
    cout << ans << endl;
}

