    vector<int64_t> B = highest; int64_t cur = 0;
    for(int i=1; i<=N; i++){
      if(bits >> (i-1) & 1){
        if(A[i] <= B[i-1]){
          cur += B[i-1]-A[i]+1;
          B[i] = B[i-1]+1;
        }
      } else {
        B[i] = max(B[i-1], A[i]);
      } 
    }
    ans = min(ans, cur);
  }
  cout << ans << endl;
}

