LL sub(int s) {
	LL prev = 0;
	LL sum = 0;
	REP(i, 0, N) {
		LL h = A[i];
		if (s >> i & 1) {
			if (A[i] <= prev) {
				sum += prev - A[i] + 1;
			}
			h = max(prev + 1, A[i]);
		}
		prev = max(prev, h);
	}
	return sum;
}

