  vector<ll> H(N);
  for(ll i=0; i<N; i++){
    cin >> H[i];
  }
  ll ans = -1;
  for(ll bit=0; bit<(1LL<<N); bit++){
    if(__builtin_popcount(bit) < K) continue;
    ll sum = 0;
    vector<ll> temp;
    temp = H;
    for(ll i=0; i<N; i++){
      if(bit & (1LL<<i)){
          ll h = temp[i];
          for(ll j=0; j<i; j++){
            chmax(h,temp[j]);
          }
          if(h != temp[i]){
            temp[i] = h+1LL;
          }
          sum += temp[i] - H[i];
      }
    }
    if(ans == -1){
      ans = sum;
    }
    chmin(ans,sum);
  }
  cout << ans << endl;
  return 0;
}

