class BBuildingsAreColorful {
public:
	void solve(std::istream& in, std::ostream& out) {
	    int n, k;
	    in >> n >> k;
	    vector<ll> a(n);
	    for(int i=0; i<n; i++){
	        in >> a[i];
	    }

	    ll res = inf;
	    for(int bit=0; bit<(1<<n); bit++){
	        vector<ll> build = a;
	        ll money = 0;
	        ll mx = build[0];
	        for(int i=1; i<n; i++){
	            if(bit & (1<<i)){
	                ll expense = max(mx-build[i]+1, 0LL);
                    build[i] += expense;
                    money += expense;
                    chmax(mx, build[i]);
                }
	        }

	        int see = 1;
	        mx = build[0];
	        for(int i=1; i<n; i++){
                if(mx < build[i]){
                    see++;
                    mx = build[i];
                }
	        }
	        if(see >= k) chmin(res, money);
	    }

	    out << res << enl;
	}
};


