// https://atcoder.jp/contests/s8pc-4/tasks/s8pc_4_b

int main() {
  int n, k;
  cin >> n >> k;
  vector<uint64_t> a(n, 0); 
  for (int i = 0; i < n; ++i) cin >> a[i];

  uint64_t ans = 10e18;
  for (int bit = 0; bit < (1 << (n)); ++bit) {
    if (bitset<32>(bit).count() != (size_t)k-1) continue;
    // 最初のビルは必ず使い、残りのk-1個の組み合わせを決めるため最初のビットが入ってk-1になっている場合は除外
    if (bit & 1) continue;

    uint64_t total = 0;
    uint64_t lastHeight = a[0];
    for (int i = 1; i < n; ++i) {
      if (!(bit & (1 << i))) continue;
      if (a[i] > lastHeight) {
        lastHeight = a[i];
      } else if (a[i] == lastHeight) {
        ++total;
        lastHeight = a[i] + 1;
      } else {
        total += (lastHeight - a[i]) + 1;
        ++lastHeight;
      }
    }
    ans = min(ans, total);
  }
  cout << ans << endl;
  return 0;
}

