void next_combination(int n,int k,vector<int>& ret) {
    if (ret[0] == n-k) return;
    int cnt = 1,b;
    while (ret.back() == n-cnt) ret.pop_back(),cnt++;
    b = ret.back();
    ret.pop_back();
    for (int i = b+1;i < b+1+cnt;++i) ret.push_back(i);
}

