long long pow2(long long x){
	long long r=1;
	while(x!=0){r*=2;x--;}
	return r;
}

long long bc(long long x){
	long long r=0;
	while(x!=0){r+=(x%2);x/=2;}
	return r;
}

long long calc(long long d,long long x[]){
	long long r = 0,i,m;
	m = x[1];d/=2;
	for(i = 2;i <= 15;i++){
		if(d%2){
			if(m < x[i]){m = x[i];}
			else{r+=(m+1-x[i]);m++;}
		}
		d/=2;
	}
	return r;
}

