typedef long long int int64;

#define MAX(a,b) ((a)>(b)?(a):(b))
#define MIN(a,b) ((a)<(b)?(a):(b))

void run(void){
  int n,k;
  scanf("%d%d",&n,&k);
  int a[15];
  int i;
  for(i=0;i<n;i++) scanf("%d",a+i);
  int64 ans=1000000000LL*n;
  for(i=1;i<(1<<n);i++){
    int cnt=0;
    int t=i;
    while(t){
      cnt+=t&1;
      t>>=1;
    }
    if(cnt!=k) continue;
    int64 local=0;
    int max=0;
    for(int j=0;j<n;j++){
      if((i>>j)&1){
	int t=MAX(max+1,a[j]);
	local+=t-a[j];
	max=MAX(max,t);
      } else {
	max=MAX(max,a[j]);
      }
    }
    ans=MIN(ans,local);
  }
  printf("%lld\n",ans);
}

int main(void){
  run();
  return 0;
}

