#include<stdio.h>
long long a[15],M=0;

long long search(int s,int e,int k){
	long long min,m,d,t;
	m=M;
	if(k>0){
		if(M<a[s]){
			M=a[s];
			t=search(s+1,e,k-1);
			M=m;
			return t;
		}
		d=M+1-a[s];
		a[s]+=d;
		M++;
		min=d+search(s+1,e,k-1);
		M--;
		a[s]-=d;
		if(e-s>k){
			t=search(s+1,e,k);
			min=(t<min)?t:min;
		}
		return min;
	}else return 0;
}

