// 内部変数 - テスト用
#ifdef D_TEST
	static int siRes;
	static FILE *szpFpA;
#endif

// 最小金額 - セット
int
fSetMin(
	int *pipWatch				// <I> 見える建物
)
{
	int i;

	// 合計金額 - 取得
	int liNow = si1Build[0];
	long long llSum = 0;
	for (i = 1; i < siBCnt; i++) {
		if (si1Build[i] > liNow) {					// 以前より大きい
			liNow = si1Build[i];
		}
		else {										// 以前より小さい
			if (pipWatch[i] == D_ON) {					// 見える建物
				int liUp = liNow - si1Build[i] + 1;
				llSum += liUp;
				liNow = si1Build[i] + liUp;
			}
		}
	}

	// 最小金額 - 更新
	if (slMin > llSum) {
		slMin = llSum;
	}

	return 0;
}

// 見える建物 - 選択
int
fSelBuild(
	int piBNo					// <I> 建物
	, int *pipWatch				// <I> 見える建物
	, int piWCnt				// <I> 見える建物数
)
{
	// 終了チェック
	if (piWCnt == siWCnt) {
		fSetMin(pipWatch);
		return 0;
	}

	// 選択 - あり
	pipWatch[piBNo] = D_ON;
	fSelBuild(piBNo + 1, pipWatch, piWCnt + 1);
	pipWatch[piBNo] = D_OFF;

	// 選択 - なし
	if (siBCnt - piBNo > siWCnt - piWCnt) {		// 残建物数 > 必要選択数
		fSelBuild(piBNo + 1, pipWatch, piWCnt);
	}

	return 0;
}

