    var minCost = 1L.shl(60)
    for (mask in bitFixedSizeSubsets(k, n)) {
        val bits = bitCollect(mask, n)
        var cost = 0L
        var pre = 0L
        for (b in bits) {
            pre = Math.max(pre, preCond[b])
            if (pre >= a[b]) {
                cost += pre + 1 - a[b]
                pre++
            } else {
                pre = a[b]
            }
        }
        minCost = Math.min(minCost, cost)
    }
    println(minCost)
