        x = (t + 1).or( (t.inv().and(-t.inv()) - 1).shr(Integer.numberOfTrailingZeros(x) + 1) )
    }
    return ret
}

fun bitFilter(mask: Int, v: LongArray): LongArray {
    val ret = LongArray(Integer.bitCount(mask))
    var cnt = 0
    for (i in 0 until v.size) {
        if (mask.shr(i) and 1 == 1) {
            ret[cnt++] = v[i]
        }
    }
    return ret
}

class IO {
    val printable = 33..126
    val buffer = ByteArray(1024)
    var ptr = 0
    var buflen = 0
    val out = PrintWriter(System.out)
    fun hasNextByte(): Boolean {
        if (ptr < buflen) {
            return true
        } else {
            ptr = 0
            buflen = System.`in`.read(buffer)
            if (buflen <= 0) {
                return false
            }
        }
        return true
    }
    fun readByte(): Byte {
        return if (hasNextByte()) buffer[ptr++] else return -1
    }
