        int k = in.nextInt();
        long[] a = new long[n];
        for (int i = 0; i < n; i++) {
            a[i] = in.nextInt();
        }
        int sz = 1 << n;
        long min = Long.MAX_VALUE;
        for (int i = 0; i < sz; i++) {
            long cost = 0;
            long pre = 0;
            int cnt = 0;
            for (int j = 0; j < n; j++) {
                if(a[j] > pre) cnt++;
                if((i & 1 << j) > 0) {
                    long add = pre < a[j] ? 0 : pre + 1 - a[j];
                    cost += add;
                    if(add > 0) cnt++;
                    pre++;
                }
                pre = Math.max(pre, a[j]);
            }
            if(cnt < k) continue;
            min = Math.min(min, cost);
        }
        System.out.println(min);
    }
