  private static void solve() {
      //String s = sc.next();
      int n = sc.nextInt();
      int kk = sc.nextInt();
      int[] arr = sc.readArray(n);
      int[] leftMax = new int[n];
      leftMax[0] = arr[0];
      int[] canSeeCnt = new int[n];
      canSeeCnt[0] = 1;
      for(int i = 1; i < n; i++) {
        leftMax[i] = Math.max(leftMax[i-1], arr[i]); 
        canSeeCnt[i] = canSeeCnt[i-1];
        if(arr[i] > leftMax[i-1])
          canSeeCnt[i]++;
      }

      int minCost = Integer.MAX_VALUE;
      for(int i = 1; i < n; i++) {
        int need = kk - canSeeCnt[i-1];
        int len = n - i;

        for(int j = 0; j < (1 << len); j++) {
          int cost = 0;
          int bitCnt = Integer.bitCount(j);
          if(bitCnt != need) continue;

          int[] leftMaxLocal = leftMax.clone();
          for(int k = 0; k < len; k++) {
            if(((j >> (len - k - 1)) & 1) == 1) {
              int idx = k + i;
              if(arr[idx] > leftMaxLocal[idx - 1]) {
                cost = cost;
              } else {
                cost += leftMaxLocal[idx - 1] + 1 - arr[idx];
                leftMaxLocal[idx] = leftMaxLocal[idx - 1] + 1;
              }
            } else {
              leftMaxLocal[k+i] = Math.max(leftMaxLocal[k+i-1], leftMaxLocal[k+i]);
            }
          }

          minCost = Math.min(minCost, cost);
        }
      }

      out.println(minCost);
  }

