public class Main {
    static InputStream is;
    static PrintWriter out;
    static String INPUT = "";

    static void solve() {
        // Initialize.
        int N = ni();
        int K = ni();
        int[] buildings = new int[N];
        for (int i = 0; i < N; i++) {
            buildings[i] = ni();
        }
        // Bit 全探索
        int min = Integer.MAX_VALUE;
        for (int bit = 0; bit < (1 << N); bit++) {
            // K 個以上のビルが見える時のパターンのみ探索。
            if (Integer.bitCount(bit) >= K) {
                // 最初のビルの高さを基準にする。
                // さもないと、最初のビルの高さが０になってしまう。
                int currentMax = buildings[0];
                int add = 0;
                for (int i = 0; i < N; i++) {
                    // 見えるビルについて高さの検証。
                    if ((bit & (1 << i)) != 0) {
                        // 前のビルより高ければ、現時点で最高の高さを
                        // 更新。
                        if (buildings[i] >= currentMax) {
                            currentMax = buildings[i];
                        } else {
                            // 低ければ、高さを上げる。
                            add += (currentMax + 1 - buildings[i]);
                            currentMax = currentMax + 1;
                        }
                    }
                }
                min = Math.min(min, add);
            }
        }

        out.println(min);
    }

