    static class B {
        public void solve(int testNumber, MyScanner in, PrintWriter out) {
            int N = in.Int();
            int K = in.Int();
            long[] a = in.Long(N);

            long ans = (long) 1e12;
            int m = 1 << N;
            for (int p = 0; p < m; p++) {
                if ((p & 1) != 1) continue;
                if (Integer.bitCount(p) != K) continue;
                long temp = 0;
                long max = a[0];
                for (int i = 1; i < N; i++) {
                    if (((p >> i) & 1) != 1) continue;
                    if (a[i] < max + 1) {
                        temp += max + 1 - a[i];
                        max += 1;
                    } else {
                        max = a[i];
                    }
                }
                ans = Math.min(ans, temp);
            }
            out.println(ans);
        }

    }

