	static void solve()
	{
		int n = ni(), K = ni();
		int[] a = na(n);
		long min = Long.MAX_VALUE;
		for(int i = 0;i < 1<<n;i++){
			if(Integer.bitCount(i) == K){
				int mh = 0;
				long plus = 0;
				for(int j = 0;j < n;j++){
					if(i<<~j<0){
						plus += Math.max(mh-a[j]+1, 0);
						mh = Math.max(mh, a[j]+Math.max(mh-a[j]+1, 0));
					}else{
						mh = Math.max(mh, a[j]);
					}
				}
				min = Math.min(min, plus);
			}
		}
		out.println(min);
	}

