public class Main {
    static int INF = (1 << 30) - 1;
    // static long L_INF = (1L << 62) - 1;
    // static long MOD = (long) 1e9 + 7;

    static class Solver {
        int N, K;
        int[] A;

        // write your code
        void solve(InputReader in, PrintWriter out) {
            N = in.nextInt();
            K = in.nextInt();
            A = new int[N];
            for (int i = 0; i < N; i++) {
                A[i] = in.nextInt();
            }

            int[] maxes = new int[N + 1];
            for (int i = 0; i < N; i++) {
                maxes[i + 1] = Math.max(maxes[i], A[i]);
            }

            int ans = INF;
            for (int i = 0; i < (1 << N); i++) {
                if (Integer.bitCount(i) != K) {
                    continue;
                }
                ArrayList<Integer> al = new ArrayList<>();
                int bit = i;
                int d = 0;
