                    d++;
                }
                int cost = 0;
                int before = 0;
                for (int j = 0; j < al.size(); j++) {
                    int idx = al.get(j);
                    int v = A[idx];
                    if (v <= Math.max(before, maxes[idx])) {
                        cost += Math.max(before, maxes[idx]) - v + 1;
                        before = Math.max(before, maxes[idx]) + 1;
                    }
                }
                ans = Math.min(ans, cost);
            }
            out.println(ans);
