public class Main {
    static InputStream is;
    static PrintWriter out;
    static String INPUT = "";

    static void solve() {
        // Initialize.
        int N = ni();
        int K = ni();
        int[] buildings = new int[N];
        for (int i = 0; i < N; i++) {
            buildings[i] = ni();
        }
        // Bit 全探索
        long min = Long.MAX_VALUE;
        for (int bit = 0; bit < (1 << N); bit++) {
            // K 個以上のビルが見える時のパターンのみ探索。
            if (Integer.bitCount(bit) >= K) {
                int currentMax = 0;
                long add = 0;
                for (int i = 0; i < N; i++) {
                    // 見える・見えないビルについて高さの検証。
                    // 見える場合は、前のビルより高さを+1大きくするないし
                    // すでに高い場合はそのままにする。
                    // 見えない場合は現時点で最高の高さを更新する。
                    if ((bit & (1 << i)) != 0) {
                        add += Math.max(0, currentMax - buildings[i] + 1);
                        currentMax = Math.max(currentMax + 1, buildings[i]);
                    } else {
                        currentMax = Math.max(currentMax, buildings[i]);
                    }
                }
                min = Math.min(min, add);
            }
        }

        out.println(min);
    }

    public static void main(String[] args) throws Exception {
        long S = System.currentTimeMillis();
        is = INPUT.isEmpty() ? System.in : new ByteArrayInputStream(INPUT.getBytes());
        out = new PrintWriter(System.out);

        solve();
        out.flush();
        long G = System.currentTimeMillis();
        tr(G-S+"ms");
    }

