    static class B {
        public void solve(int testNumber, MyScanner in, PrintWriter out) {
            int N = in.Int();
            int K = in.Int();
            long[] a = in.Long(N);

            long ans = 1L << 60;
            int m = 1 << N;
            for (int p = 0; p < m; p++) {
                long temp = 0;
                long max = 0;
                int cnt = 0;
                for (int i = 0; i < N; i++) {
                    long len = a[i];
                    if (((p >> i) & 1) == 1) {
                        if (len < max + 1) {
                            temp += max + 1 - len;
                            len = max + 1;
                        }
                    }
                    if (max < len) {
                        max = len;
                        cnt++;
                    }
                }
                if (cnt >= K) {
                    ans = Math.min(ans, temp);
                }
            }
            out.println(ans);
        }

    }

