			long b[] = a.clone();
			boolean flag[] = new boolean[n];
			flag[0] = true;

			int count = 0;
			for (int i = 0; i < n; i++) {
				if ((bit & (1 << i)) != 0) {
					flag[i] = true;
					count++;
				}
