			long b[] = a.clone();
			boolean flag[] = new boolean[n];
			flag[0] = true;

			int count = 0;
			for (int i = 0; i < n; i++) {
				if ((bit & (1 << i)) != 0) {
					flag[i] = true;
					count++;
				}
			}

			if (count < k)
				continue;

			long sum = 0;
			for (int i = 0; i < n; i++) {
				long height = 0;
				if (flag[i]) {
					for (int j = 0; j < i; j++) {
						if (flag[j]) {
							height = b[j];
						}
					}
					if (height >= b[i]) {
						sum += height + 1 - b[i];
						b[i] += height + 1 - b[i];
					}
				}
			}
			ans = Math.min(ans, sum);
		}
		System.out.println(ans);
	}
}

