			int maxh = 0;
			int count = 0;
			long cost = 0;
			for(int j = 0;j < N;j++){

				int add = 0;

				if(maxh >= a[j]){
					if((i>>j&1) == 1){
						add = (maxh - a[j] + 1);
						cost += add;
						count++;
					}
				}else{
					count++;
				}
				maxh = Math.max(maxh, a[j] + add);
			}

			if(count >= K)ans = Math.min(ans, cost);
		}

		out.println(ans);
	}
