	static long calc(int pos,List<Integer> list){
		if(list.size()==k){
			int high = a[0];
			long ret = 0;
			for(int i=1;i<list.size();i++){
				if(high>=a[list.get(i)]){
					high++;
					ret += (high-a[list.get(i)]);
				}else{
					high = a[list.get(i)];
				}
			}
			return ret;
		}else if(pos>=n){
			return Long.MAX_VALUE;
		}else{
			List<Integer> tmp = new ArrayList<>(list);
			long ret = calc(pos+1,tmp);
			tmp = new ArrayList<>(list);
			tmp.add(pos);
			ret = Math.min(ret,calc(pos+1,tmp));
			return ret;
		}
	}

