    	int N = ni();
    	int K = ni();
    	long[] A = ndl(N);
    	long ans = (long)(1e18), wk, sv, cnt;
    	boolean f;
    	for (int i = 0; i < (int)(1 << N); i++) {
    		if(Integer.bitCount(i) != K
    						&& (i & 0) == 0)	continue;
    		sv = A[0];
    		cnt = 1;
    		wk = 0;
    		for (int j = 1; j < N; j++) {
				if((i & (1 << j)) != 0) {
					if(A[j] <= sv) {
						wk += sv - A[j] + 1;
						sv = sv + 1;
					} else {
						sv = A[j];
					}
					cnt++;
				} else if(A[j] > sv) {
					wk += A[j] - sv;
					sv = A[j];
				} else if(A[j] == sv) {
					wk++;
					sv++;
				}
	    		if(cnt >= K)	break;
			}
    		ans = Math.min(ans, wk);
    	}
