			final int N = sc.nextInt();
			final int K = sc.nextInt();

			long[] array = new long[N];
			for(int i = 0; i < N; i++){
				array[i] = sc.nextLong();
			}

			long answer = Long.MAX_VALUE;
			for(int i = 0; i < (1 << N); i++){
				if(Integer.bitCount(i) != K){ continue; }

				long price = 0;
				long max = 0;
				for(int j = 0; j < N; j++){
