//				out.println(" i = " + Integer.toBinaryString(i) + "  sv = " + sv);
				for (int j = 1; j < N; j++) {
					if((i & (1 << j)) != 0) {
						if(A[j] <= sv) {
							sum += sv - A[j] + 1;
							sv++;
//							out.println(" A[" + j + "] = " + A[j] + "  sum = " + sum + "  sv = " + sv);
						} else {
							sv = A[j];
//							out.println(" A[" + j + "] = " + A[j] + "  sv = " + sv);
						}
					} else if(A[j] > sv) {
						sum += A[j] - sv;
						sv = A[j];
					}
				}
				ans = Math.min(ans, sum);
			}
		}
		out.println(ans);
	}

