            long result = long.MaxValue;
            for (int i = 0; i < (1 << N); i++)
            {
                if(Enumerable.Range(0, N).Where(j => (i & (1 << j)) > 0).Count() != K) continue;

                long sum = 0, prev = list.First();
                for (int j = 1; j < N; j++)
                {
                    if ((i & (1 << j)) > 0)
                    {
                        if (prev >= list[j])
                        {
