        for (int i = 1; i < k; i++)
        {
            if (a[i-1] >= a[i])
            {
                int tmp = a[i-1] - a[i] + 1;
                cost += tmp;
                a[i] += tmp;
            }
        }
        Console.WriteLine(cost);
    }
