		{
			var firstLine = Console.ReadLine().Split(' ').Select(value => int.Parse(value)).ToList();
			var n = firstLine[0];
			var k = firstLine[1];

			var buildings = Console.ReadLine().Split(' ').Select(value => long.Parse(value)).ToList();

			var min = long.MaxValue;

			for(var bit = 0; bit < (1 << n); bit++)
			{
				var count = 0;
				for(var i = 0; i < n; i++)
				{
					if(((bit >> i) & 1) == 1)
					{
						count++;
					}
					else if(i == 0)
					{
						break;
					}
				}

				if(count != k)
				{
					continue;
				}

				long maxHeight = 0;
				long cost = 0;

				for(var i = 0; i < n; i++)
				{
					if(i == 0)
					{
						maxHeight = buildings[i];
						continue;
					}

