    static void Main()
    {
        var sc = new Scanner();

        int n = sc.NextInt();
        int k = sc.NextInt();

        int[] height = sc.IntArray();

        long answer = long.MaxValue;

        for (int i = 0; i < Math.Pow(2, n); i++)
        {
            long price = 0;

            int count = 0;
            for (int j = 0; j < n; j++)
            {
                if ((1 & (i >> j)) == 1)
                {
                    count++;
                }
            }
            if (count < k)
            {
                continue;
            }

            int min = 0;

            for (int j = 0; j < n; j++)
            {
                if ((1 & (i >> j)) == 1)
                {
                    if (height[j] <= min)
                    {
                        price += min + 1 - height[j];
                    }
                    min = Math.Max(min + 1, height[j]);
                }
                else
                {
                    min = Math.Max(min, height[j]);
                }
            }

            answer = Math.Min(answer, price);
        }

        Console.WriteLine(answer);
    }

