class Program
{
    static int N;
    static int K;
    static long[] a;
    static long inf = (long)1e15;

    static void Main()
    {
        string[] s = Console.ReadLine().Split();
        N = int.Parse(s[0]);
        K = int.Parse(s[1]);
        a = Console.ReadLine().Split().Select(long.Parse).ToArray();

        Pair[,] dp = new Pair[N, N + 1];
        dp[0, 0].cost = 0;
        dp[0, 0].max = a[0];
        dp[0, 1].cost = 0;
        dp[0, 1].max = a[0];
        for (int j = 2; j <= N; j++)
        {
            dp[0, j].cost = inf;
            dp[0, j].max = a[0];
        }

        for (int i = 1; i < N; i++)
        {
            dp[i, 0].cost = dp[i - 1, 0].cost;
            dp[i, 0].max = Max(dp[i - 1, 0].max, a[i]);
            for (int j = 1; j <= N; j++)
            {
                long l = dp[i - 1, j].cost;
                long r = dp[i - 1, j - 1].cost;
                if (dp[i - 1, j - 1].max >= a[i])
                    r += dp[i - 1, j - 1].max + 1 - a[i];
                if (l <= r)
                {
                    dp[i, j].cost = l;
                    dp[i, j].max = Max(dp[i - 1, j].max, a[i]);
                }
                else
                {
                    dp[i, j].cost = r;
                    if (dp[i - 1, j - 1].max >= a[i]) dp[i, j].max = dp[i - 1, j - 1].max + 1;
                    else dp[i, j].max = a[i];
                }
            }
        }
