        for (int i = 0; i < N; i++)
        {
            for (int j = 0; j <= N; j++)
                Console.Write("({0},{1}) ", dp[i, j].cost, dp[i, j].max);
            Console.WriteLine();
        }
#endif
        Console.WriteLine(dp[N - 1, K].cost);
    }
}

