public static class CombEnum {
	// 要素をシーケンスに追加するユーティリティ
	private static IEnumerable<T> Before<T>(IEnumerable<T> items, T first) {
		yield return first;
		foreach (var i in items) yield return i;
	}
	// 順列
	public static IEnumerable<IEnumerable<T>> Perm<T>(IEnumerable<T> items, int r = -1, bool withRepetition = false) {
		if (r < 0) r = items.Count();
		if (r == 0) {
			yield return Enumerable.Empty<T>();
		} else {
			var i = 0;
			foreach (var x in items) {
				var xs = withRepetition ? items : items.Where((_, index) => i != index);
				foreach (var c in Perm(xs, r - 1, withRepetition)) yield return Before(c, x);
				i++;
			}
		}
	}
	// 組合せ
	public static IEnumerable<IEnumerable<T>> Comb<T>(IEnumerable<T> items, int r, bool withRepetition = false) {
		if (r == 0) {
			yield return Enumerable.Empty<T>();
		} else {
			var i = withRepetition ? 0 : 1;
			foreach (var x in items) {
				var xs = items.Skip(i);
				foreach (var c in Comb(xs, r - 1, withRepetition)) yield return Before(c, x);
				i++;
			}
		}
	}

	// 直積
	private static IEnumerable<T> Fold<T>(IEnumerable<T> source, Func<T, IEnumerable<T>, IEnumerable<T>> proc, IEnumerable<T> init) => 
		!source.GetEnumerator().MoveNext() ? init : Fold(source.Skip(1), proc, proc(source.ElementAt(0), init));
	public static IEnumerable<IEnumerable<T>> DirectProduct<T>(IEnumerable<IEnumerable<T>> sets) =>
		Fold(sets, (list, prod) => from x in prod from y in list select x.Concat(Enumerable.Repeat(y, 1)), Enumerable.Repeat(Enumerable.Empty<T>(), 1));


}














