public class CP {
  public void Solve () {
    var (N, K) = Cin<int, int> ();
    var a = Cinarr<long> ();
    long ans = INFL;
    long[] ruimax = new long[N + 1];
    for (int i = 0; i < N; ++i) {
      ruimax[i + 1] = Max (ruimax[i], a[i]);
    }
    for (int i = 0; i < (1 << N); ++i) {
      var grow = new List<int> ();
      for (int j = 0; j < N; ++j) {
        if (((i >> j) & 1) == 1) grow.Add (j);
      }
      if (grow.Count < K) continue;
      long sum = 0;
      long last = ruimax[grow[0]];
      for (int j = 0; j < grow.Count; ++j) {
        if (a[grow[j]] > last) {
          last = a[grow[j]];
        } else {
          last = last + 1;
          sum += last - a[grow[j]];
        }
      }
      ans = Min (ans, sum);
    }
    Put (ans);
  }
}

public static class Math2 {
  public const int INF = 1 << 29;
  public const long INFL = 1L << 60;
  public const long MOD = 1000000007;
  public const long MOD2 = 998244353;

  public static long Power (long a, long b, long MOD = 1000000007) //i^N
  {
    long res = 1;
    while (b > 0) {
      if ((b & 1) != 0) res = res * a % MOD;
      a = a * a % MOD;
      b >>= 1;
    }
    return res;
  }
  public static long Power2 (long a, long b) //i^N
  {
    long res = 1;
    while (b > 0) {
      if ((b & 1) != 0) res = res * a;
      a = a * a;
      b >>= 1;
    }
    return res;
  }
  public static long GCD (long a, long b) {
    while (b > 0) {
      var r = a % b;
      a = b;
      b = r;
    }
    return a;
  }
  public static long LCM (long a, long b) => (b / GCD (a, b)) * a;
  public static long Comb (long n, long r, int MOD = 1000000007) {
    if (r > n - r) r = n - r;
    long Nume = 1;
    long Deno = 1;

    if (r > n - r) r = n - r;
    for (long i = 1; i <= r; ++i) {
      Deno = (Deno * i) % MOD;
      Nume = Nume * (n - i + 1) % MOD;
    }
    return (Nume * inv (Deno)) % MOD;
  }
  public static long Comb2 (long n, long r) {
    long Nume = 1;
    long Deno = 1;

    if (r > n - r) r = n - r;
    for (long i = 1; i <= r; ++i) {
      Deno *= i;
      Nume *= n - i + 1;
    }
    return Nume / Deno;
  }
  public static long inv (long x, int MOD = 1000000007) {
    return Power (x, MOD - 2, MOD);
  }
}
