		var a = GetLongs(N);

		long ans = long.MaxValue;
		for(int s = 0, E = (1 << N); s < E; s++)
		{
			if(popcnt(s) < K)
				continue;

			long sum = 0;
			long max = 0;
			for(int i = 0; i < N; i++)
			{
				if(contains(s, i))
				{
					if(a[i] > max)
					{
						max = a[i];
					}
					else
