package main

import (
	"fmt"
	"strings"
)

func main() {
	var n, k int
	fmt.Scan(&n, &k)
	a := make([]int, n)
	for i := 0; i < n; i++ {
		fmt.Scan(&a[i])
	}

	ans := int(1e18)
	for b := 0; b < (1 << uint(n-1)); b++ {
		bits := b | (1 << uint(n-1))
		c := strings.Count(fmt.Sprintf("%b", bits), "1")
		if c < k {
			continue
		}

		mx := a[0]
		sum := 0
		for i := 1; i < n; i++ {
			if bits&(1<<uint(i)) == 0 || mx < a[i] {
				mx = max(mx, a[i])
				continue
			}
			mx++
			sum += mx - a[i]
		}
		ans = min(ans, sum)
	}

	fmt.Println(ans)
}

func min(a, b int) int {
	if a < b {
		return a
	}
	return b
}

func max(a, b int) int {
	if a > b {
		return a
	}
	return b
}

