			m[i] = a[i]
			max = a[i]
		} else {
			m[i] = max
		}
	}
	if K == 1 {
		fmt.Println(m[N-1] - a[0])
		return
	}
	r := math.MaxInt64
	for bit := (1 << uint(K)) - 1; bit < (1 << uint(N)); bit = next_combination(bit) {
