func calc(a, m, q []int) int {
	sum := 0
	w := make([]int, len(m))
	copy(w, m)
	for i := 0; i < len(q); i++ {
		if w[q[i]] > a[q[i]] {
			sum += w[q[i]] + 1 - a[q[i]]
			w[q[i]]++
			for j := q[i] + 1; j < len(w); j++ {
				if w[j-1] > w[j] {
					w[j] = w[j-1]
				}
			}
		}

	}
	return sum
}

func next_combination(sub int) int {
	x := sub & -sub
	y := sub + x
	return (((sub & ^y) / x) >> 1) | y
}

