                }

                ansT := 0
                tall := a[0]
                for j, v := range strings.Split(s, "") {
                        if v != "1" {
                                continue
                        }
                        if a[j+1] > tall {
                                ansT = ansT + a[j+1] - tall
                                tall = a[j+1]
                        } else {
                                ansT = ansT + tall + 1 - a[j+1]
                                tall = tall + 1
                        }
                }
                ans = min(ans, ansT)
        }
        fmt.Println(ans)
}

