func main() {
	n, k = ReadInt2()
	A = ReadIntSlice(n)

	ans := INF_BIT60
	BruteForceByBits(n, func(mask []bool) {
		num := 0
		for _, b := range mask {
			if b {
				num++
			}
		}
		if num < k {
			return
		}

		curH := 0
		cost := 0
		for i := 0; i < n; i++ {
			if !mask[i] {
				ChMax(&curH, A[i])
				continue
			}

			if A[i] > curH {
				ChMax(&curH, A[i])
			} else {
				diff := curH - A[i]
				cost += diff + 1
				ChMax(&curH, A[i]+diff+1)
			}
		}

		ChMin(&ans, cost)
	})

	fmt.Println(ans)
}

// Max returns the max integer among input set.
// This function needs at least 1 argument (no argument causes panic).
func Max(integers ...int) int {
	m := integers[0]
	for i, integer := range integers {
		if i == 0 {
			continue
		}
		if m < integer {
			m = integer
		}
	}
	return m
}

// ChMax accepts a pointer of integer and a target value.
// If target value is LARGER than the first argument,
//	then the first argument will be updated by the second argument.
func ChMax(updatedValue *int, target int) bool {
	if *updatedValue < target {
		*updatedValue = target
		return true
	}
	return false
}

// ChMin accepts a pointer of integer and a target value.
// If target value is SMALLER than the first argument,
//	then the first argument will be updated by the second argument.
func ChMin(updatedValue *int, target int) bool {
	if *updatedValue > target {
		*updatedValue = target
		return true
	}
	return false
}

// BruteForceByBits(10, func(b []bool) { fmt.Println(b) }
// -> [false, false, false, false, false, false, false, false, false, false]
//    [true, false, false, false, false, false, false, false, false, false]
//    [false, true, false, false, false, false, false, false, false, false]
//    [true, true, false, false, false, false, false, false, false, false]
//    [false, false, true, false, false, false, false, false, false, false]
//    ...
// originated from ktateish@atcoder
// e.g.: https://atcoder.jp/contests/abc167/submissions/13042361
func BruteForceByBits(l int, fn func([]bool)) {
	L := 1 << uint(l)
	mask := make([]bool, l)
	for i := 0; i < L; i++ {
		for j := 0; j < l; j++ {
			k := l - j - 1
			if i&(1<<uint(j)) == 0 {
				mask[k] = false
			} else {
				mask[k] = true
			}
		}
		fn(mask)
	}
}

