func solve(scanner *bufio.Scanner, writer *bufio.Writer) {
	n := getNextInt(scanner)
	k := getNextInt(scanner)
	aa := make([]int, n)
	mm := make([]int, n+1)
	for i := 0; i < n; i++ {
		aa[i] = getNextInt(scanner)
		if mm[i] > aa[i] {
			mm[i+1] = mm[i]
			continue
		}
		mm[i+1] = aa[i]
	}

	var ans, s int64
	ans = math.MaxInt64
	for b := 0; b < 1<<uint(n); b++ {
		sum := 0
		m := 0
		for i := 0; i < n; i++ {
			sum += b >> uint(i) & 1
		}
		if sum < k {
			continue
		}
		s = 0
		for i := 0; i < n; i++ {
			if b>>uint(i)&1 == 0 {
				continue
			}
			m = maxint(m, mm[i])
			if aa[i] < m+1 {
				s += int64(m + 1 - aa[i])
			}
			m = maxint(aa[i], m+1)
		}
		if ans > s {
			ans = s
		}
	}
	fmt.Fprintln(writer, ans)
}

func maxint(a, b int) int {
	if a < b {
		return b
	}
	return a
}

