    int n = cast(int) a.length;
    for (int i = 1; i < (1 << n); i++) {
        int[] selected;
        for (int j = 0; j < n; j++) {
            if (i & (1 << j)) {
                selected ~= a[j];
            }
        }

        if (selected.length == k) {
            int h = selected[0];
            int cost = 0;
            for (int j = 1; j < selected.length; j++) {
                if (h < selected[j]) {
                    h = selected[j];
                }
                else {
                    // selected[j] を h+1 まで増やす
                    cost += (h + 1) - selected[j];
                    h = h + 1;
                }
            }
            ans = min(ans, cost);
        }
    }
    return ans;
}

void main() {
    auto nk = readints;
    int k = nk[0];
    auto a = readints;
    writeln(calc(k, a));
}

