def solve(idx):
    ret = 0
    tmpmax = A[idx[0]]
    for i in range(1, len(idx)):
        if A[idx[i]] <= tmpmax:
            ret += tmpmax - A[idx[i]] + 1
            tmpmax += 1
        else:
            tmpmax = A[idx[i]]
    return ret

