def resolve():
    N, K = map(int, input().split())
    A = list(map(int, input().split()))

    ans = 1 << 60
    for bit in range(1 << N):
        bills = A[:]
        # K個の建物が必要
        if bin(bit).count("1") != K:
            continue
        sum_H = 0
        cmb = []  # 建物の組み合わせ
        for i in range(N):
            if bit >> i & 1:
                cmb.append(i)
        for b in cmb:
            if b == 0:
                continue
            m = max(bills[:b])
            if m < bills[b]: # 後ろの建物が高かい場合、伸ばす必要なし
                pass
            else:
                sum_H += m + 1 - bills[b] # 伸ばすコスト
                bills[b] = m + 1 # 伸ばした高さに修正
        ans = min(ans, sum_H)

    return print(ans)

if __name__ == "__main__":
    resolve()

