def b_buildings_are_colorful(N, K, A):
    import itertools
    combination = itertools.combinations(range(1, N), K - 1)
    ans = float('inf')
    for comb in combination:
        tmp = A[:]
        max_height = A[0]
        for k in range(1, N):
            if k in comb:
                if tmp[k] <= max_height:
                    tmp[k] = max_height + 1
            max_height = max(max_height, tmp[k])

        delta = 0
        for k in range(N):
            delta += tmp[k] - A[k]
        ans = min(ans, delta)
    return ans

