    if N == 1:
        print(0)
        sys.exit()
    myT = LI()
    result = float('inf')
    dq = deque()
    dq.append([1,myT[0],0])
    for i in range(1, N):
        new_dq = deque()
        for num, height, cost in dq:
            num1 = num+1
            height1 = max(myT[i], height+1)
            cost1 = cost + height1 - myT[i]
            if cost < result and num + N - i > K:
                new_dq.append([num, height, cost])

            if num1 == K:
                result = min(result, cost1)
                continue
            if cost1 < result and num1 + N - i > K:
                new_dq.append([num1, height1, cost1])
        if not new_dq:
            break
        else:
            dq = new_dq
    print(result)

