def dfs(height=a[0], cost=0, target=K, can_see=1, i=1):
    # もはや目的を達成しえぬ場合
    if can_see + N - i < target:
        return float('inf')
    if i >= len(a):
        return float('inf')
    if can_see >= target:
        return float('inf')

    # 建物 i を選ばない場合
    if height <= a[i]:
        cost1 = dfs(height=max(height, a[i]), cost=cost, target=K, can_see=can_see, i=i+1)
    else:
        cost1 = float('inf')
    # print('cost1', cost1, 'can_see', can_see, 'i', i)

    # 建物　i を選んだ場合
    cost += max(0, height + 1 - a[i])
    can_see += 1
    height = max(a[i], height + 1)
    if can_see == target:
        # print('height', height)
        # print('can_see', can_see)
        # print('cost', cost)
        return cost
    cost2 = dfs(height=height, cost=cost, target=K, can_see=can_see, i=i+1)
    # print('cost2', cost2)

    return min(cost1, cost2)


