    fn try_fold_<B, F>(&mut self, init: B, mut f: F) -> Option<B>
    where
        Self: Sized + Iterator,
        F: FnMut(B, Self::Item) -> Option<B>
    {
        let mut accum = init;
        while let Some(x) = self.next() {
            if let Some(new_accum) = f(accum, x) {
                accum = new_accum;
            } else {
                return None;
            }
        }
        Some(accum)
    }
}

