fn build(xs: &Vec<u64>, ns: &Vec<u64>, acc: u64) -> u64 {
    let mut highest = xs[0] - 1;
    let mut result = 0;

    for i in 0..xs.len() {
        let up = if ns.contains(&(i as u64)) {
            highest + 1 - xs[i]
        } else {
            0
        };
        result += up;
        highest = max(highest, xs[i] + up);

        if result > acc { return u64::MAX; }
    }
    result
}

fn solve(xs: Vec<u64>, n: usize, k: usize) -> u64 {
    let mut result = u64::MAX;

    for ns in (0..n as u64).combinations(k) {
        result = min(build(&xs, &ns, result), result)
    }

    result
}

