trait Ext {
    fn try_fold_<B, F>(&mut self, init: B, mut f: F) -> Option<B>
    where
        Self: Sized + Iterator,
        F: FnMut(B, Self::Item) -> Option<B>,
    {
        let mut accum = init;
        while let Some(x) = self.next() {
            if let Some(new_accum) = f(accum, x) {
                accum = new_accum;
            } else {
                return None;
            }
        }
        Some(accum)
    }
}
impl<I, St, F> Ext for Scan<I, St, F> {}

fn cost(a: &[i64], bits: u32) -> Option<i64> {
    let mut cur_height = 0;
    let mut cost = 0;
    for (i, &height) in a.iter().enumerate() {
        if (bits >> i) & 1 != 0 {
            let expected_height = max(cur_height + 1, height);
            cur_height = expected_height;
            cost += expected_height - height;
        } else if height > cur_height {
            return None;
        }
    }
    Some(cost)
}

fn solve(n: usize, k: usize, a: Vec<i64>) -> i64 {
    (0u32..(1 << n))
        .filter(|&bits| bits.count_ones() >= (k as u32))
        .filter_map(|bits| cost(&a, bits))
        .min()
        .unwrap()
}

