use std::cmp::max;
use std::io::Read;
use std::ops::Range;
use std::iter::Scan;

#[derive(Clone, Debug)]
pub struct StepBy<I> {
    iter: I,
    step: usize,
    first_take: bool,
}
impl<I> StepBy<I> {
    fn new(iter: I, step: usize) -> StepBy<I> {
        assert!(step != 0);
        StepBy { iter: iter, step: step - 1, first_take: true }
    }
}
impl<I> Iterator for StepBy<I>
where
    I: Iterator,
{
    type Item = I::Item;

    fn next(&mut self) -> Option<Self::Item> {
        if self.first_take {
            self.first_take = false;
            self.iter.next()
        } else {
            self.iter.nth(self.step)
        }
    }
}

trait Ext {
    fn step_by_(self, step: usize) -> StepBy<Self>
    where
        Self: Sized
    {
        StepBy::new(self, step)
    }

    fn try_fold_<B, F>(&mut self, init: B, mut f: F) -> Option<B>
    where
        Self: Sized + Iterator,
        F: FnMut(B, Self::Item) -> Option<B>
    {
        let mut accum = init;
        while let Some(x) = self.next() {
            accum = f(accum, x)?;
        }
        Some(accum)
    }
}

impl<T> Ext for Range<T> {
}

impl<I, St, F> Ext for Scan<I, St, F> {
}

fn cost(a: &Vec<i64>, bits: u32) -> Option<i64> {
    a.iter()
        .enumerate()
        .scan(0, |cur_height, (i, &height)| {
            let (next_height, expected_height) = if (bits >> i) & 1 != 0 {
                (max(*cur_height + 1, height), max(*cur_height + 1, height))
            } else {
                (*cur_height, height)
            };
            *cur_height = next_height;
            Some((height, expected_height))
        })
        .try_fold_(0, |cost, (height, expected_height)| {
            if height > expected_height {
                None
            } else {
                Some(cost + expected_height - height)
            }
        })
}

fn solve(n: usize, k: usize, a: Vec<i64>) -> i64 {
    (1..(1<<n))
        .step_by_(2)
        .filter(|&bits| (bits as u32).count_ones() >= (k as u32))
        .filter_map(|bits| cost(&a, bits))
        .min()
        .unwrap()
}

