use std::cmp::max as max;
use std::cmp::min as min;

use itertools::Itertools;

fn build(buildings: &Vec<u64>, build_ups: &Vec<u64>) -> u64 {
    //println!("{:?}", build_ups);
    let mut highest = buildings[0] - 1;
    let mut costs = 0;

    for i in 0..buildings.len() {
        //print!("{}: ", i);
        //print!("highest: {} ", highest);
        let cost = if build_ups.contains(&(i as u64)) {
            //print!("( if ) ");
            if highest + 1 < buildings[i] { 0 } else { highest + 1 - buildings[i] }
        } else {
            //print!("( else ) ");
            0
        };
        costs += cost;
        highest = max(highest, buildings[i] + cost);
        //print!("highest: {} ", highest);
        //println!("cost: {}\n", cost);
    }
    //println!("------");
    costs
}

fn solve(buildings: Vec<u64>, n: usize, k: usize) -> u64 {
    let mut result = 9223372036854775807;

    for build_ups in (0..n as u64).combinations(k) {
        result = min(build(&buildings, &build_ups), result)
    }

    result
}

