use std::cmp::min;


fn main() {
    let (n, k) = read_tuple::<usize>();
    let an: Vec<i64> = read_vec();

    let mut ans = i64::max_value();
    for i in 0..(1<<n) {
        if i % 2 != 1 || ((i as usize).count_ones() as usize) < k {
            continue;
        }

        let mut an = an.clone();
        let mut max_height = an[0];
        let mut cost = 0;
        for j in 1..n {
            if i & (1 << j) == (1 << j) {
                if an[j] <= max_height {
                    cost += max_height - an[j] + 1;
                    an[j] = max_height + 1;
                    max_height += 1;
                } else {
                    // an[j] > max_height
                    max_height = an[j];
                }
            } else {
                if max_height < an[j] {
                    cost = i64::max_value();
                    break;
                }
            }
        }

        ans = min(ans, cost);
    }

    println!("{}", ans);
}

